Class:
    /* Application Delegate */
    labels contains "UIApplicationDelegate"
    /* ... which contains a handler for custom URL IPC */
    and functions contains [Function:
        name == "application:handleOpenURL:"
        or name == "application:openURL:sourceApplication:annotation:"
        or name == "application:openURL:options:"
    ]*
    /* dirty workaround for bug 57838. These checks are meant to match only on instance classes. */
    and supers contains [Class: name == "objc_object"]
    and not supers contains [Class: name == "objc_class"]
    /* ... and it either does not implement any of the callbacks where validation can stop the application launching */
    and (not functions contains [Function:
        name == "application:willFinishLaunchingWithOptions:"
        or name == "application:didFinishLaunchingWithOptions:"
    ]
    /* ... or it implements it but they do not access the URL used to call the app or always return YES */
    or functions contains [Function f:
        (name == "application:willFinishLaunchingWithOptions:"
        or name == "application:didFinishLaunchingWithOptions:")
        and (
            not contains [VariableAccess:
                variable.name == "UIApplicationLaunchOptionsURLKey"
            ]
            or not contains [ReturnStatement:
                /* see bug 57773 */
                (expression.constantValues contains [String: matches "(?i)false|no"]
                or expression.constantValues contains [Number: == 0])
                or expression contains [VariableAccess:
                    variable is [Variable:
                        uses contains [VariableAccess va:
                            enclosingStatement is [AssignmentStatement:
                                lhs is [VariableAccess va2: va2 is va]
                                and (rhs.constantValues contains [String: matches "(?i)false|no"]
                                or rhs.constantValues contains [Number: == 0])
                            ]
                        ]
                    ]
                ]
            ]
        )
    ]*)

