FunctionCall:
    possibleTargets contains [Function:
        name matches "setTLS(Min|Max)imumSupportedProtocolVersion:"
        and enclosingClass.supers contains [Class:
            name == "NSURLSessionConfiguration"
        ]
    ]
    and (
        arguments[0] is [VariableAccess:
            variable.name == "tls_protocol_version_TLSv10"
            or variable.name == "tls_protocol_version_TLSv11"
            or variable.name == "tls_protocol_version_DTLSv10"
        ]*
        /* TLS1.0 is 769, TLS1.1 is 770, DTLS1.0 is 65279 */
        or arguments[0].constantValues contains [Number: < 771 or == 65279]*
    )

