        and (reaches [Function: contains [FunctionCall:
            possibleTargets contains [Function:
                (name == "credentialWithUser:password:persistence:"
                or name == "initWithUser:password:persistence:")
                and enclosingClass.supers contains [Class:
                    name == "NSURLCredential"
                ]
            ]*
        ]]
        /* or a credential that could be user/password */
        or reaches [Function: contains [FunctionCall:
            possibleTargets contains [Function:
                (name == "defaultCredentialForProtectionSpace:"
                or name == "allCredentials"
                or name == "credentialsForProtectionSpace:")
                and enclosingClass.supers contains [Class:
                    name == "NSURLCredentialStorage"
                ]
            ]*
        ]])
        /* and it sends the credential to remote server */
        and reaches [Function: contains [FunctionCall:
            possibleTargets contains [Function:
                name == "useCredential:forAuthenticationChallenge:"
                and enclosingClass.supers contains [Class:
                    name == "NSURLAuthenticationChallengeSender"
                ]
            ]*
        ]]
        /* and it does not contain a Host check */
        and not reaches [Function: contains [FunctionCall:
            possibleTargets contains [Function:
                name == "host"
                and enclosingClass.supers contains [Class:
                    name == "NSURLProtectionSpace"
                ]
            ]
        ]]
        /* and it does not contain a receivesCredentialSecurely check */
        and not reaches [Function: contains [FunctionCall:
            possibleTargets contains [Function:
                name == "receivesCredentialSecurely"
                and enclosingClass.supers contains [Class:
                    name == "NSURLProtectionSpace"
                ]
            ]
        ]]
    ]*
    and not functions contains [Function:
        name == "connection:willSendRequestForAuthenticationChallenge:"
    ]

