FieldAccess fa: 
    /* SSN numbers on field accesses are covered by cpp rule 1CFC208D-39B8-4927-B30A-B84194A94C95 */
    /* Credit card numbers on field accesses are covered by cpp rule 60F06F15-AE16-43FB-BA2A-DC6DDB4A91D8 */
    field.name matches "(?i).*pass(wd|word|phrase).*|.*token$|.*encrypt(?!ed).*|plaintext|cleartext|.*pin$"
    /* To avoid duplicates with CPP 474F56DC-DA45-405A-9F7E-D35D9BD72A8D */
    and not field.type.name == "char"

VariableAccess va: 
    /* SSN numbers on field accesses are covered by cpp rule EF8E0C2B-A5EB-4DCB-A739-010CF00ECC37 */
    /* Credit card numbers on variable accesses are covered by cpp rule 3815C8EC-88D8-435C-82C1-A2455EAFA95B */
    variable.name matches "(?i).*token$|.*encrypt(?!ed).*|plaintext|cleartext|.*pin$"
    /* To avoid duplicates with CPP C29FC47E-2378-4C96-869D-34EDD2B6741F */
    and not variable.type.name == "char"

