ControlflowRule.Definition:
state start (start);
state locked;
state mightBeLocked;
state unlocked;
state error (error);

var l;
var lockResult;
start -> locked { $lock(&l) }
start -> mightBeLocked { lockResult = $trylock(&l) }
mightBeLocked -> locked { #ifblock(@lockResult, true, true) | #ifblock(@lockResult, false, false) }
mightBeLocked -> unlocked { #ifblock(@lockResult, false, true) | #ifblock(@lockResult, true, false) | #escape(l) }
locked -> unlocked { $unlock(&@l) | #escape(l) }
locked -> error { #end_scope(l) }

state start (start);
state SMSURLInitialized;
state URLOpened (error);
var u;

start -> SMSURLInitialized { u = $initSMSURL(...) }
SMSURLInitialized -> URLOpened { $openURL(u) }

state start (start);
state safe;
state error (error);

start -> safe { $evaluate(...) | $evaluate2(...) }
start -> error { $init(...) }

state start (start);
state init;
state safe;
state error (error);

var c;

start -> init { c = $newconfiguration(...) }
init -> safe { c.$minimumTLSversion(...) }
init -> error { $session(c, ...) }

state start (start);
state allocated;
state safe;
state leak (error);
var o;

start -> allocated { o = $allocate() }
allocated -> allocated { ~o = o.$initialize(...) }
allocated -> safe { o.$free() }
allocated -> leak { #end_scope(o) | #return(o) }

state start (start);
state insufficientProtectionDictCreated;
        state fileProtectionSet;
state insufficientProtectionFileWrittenTo (error);
var d;
var f;

start -> insufficientProtectionDictCreated { d = $createInsufficientProtectionDict(?, ?) }
insufficientProtectionDictCreated -> fileProtectionSet { $setFileProtection(d, f, ?) }
fileProtectionSet -> insufficientProtectionFileWrittenTo { $write1(f, ...) | $write2(?, f) | f.$write3(...) }

state start (start);
state lackingProtectionDictCreated;
state fileProtectionSet;
state lackingProtectionFileWrittenTo (error);
var d;
var f;

start -> lackingProtectionDictCreated { d = $createLackingProtectionDict(?, ?) }
lackingProtectionDictCreated -> fileProtectionSet { $setFileProtection(d, f, ?) }
fileProtectionSet -> lackingProtectionFileWrittenTo { $write1(f, ...) | $write2(?, f) | f.$write3(...) }

state start (start);
state requestInitialized;
state safeRequestMethodSet;
state requestUsed (error);
var r;

start -> requestInitialized { r = $initRequest(...) }
requestInitialized -> safeRequestMethodSet { r.$setSafeRequestMethod(?) }
requestInitialized -> requestUsed { $any(...,r,...) }

state start (start);
state loaded;
state released;
state closed;
state ifblock;
state end_of_scope (error);
var r;
start -> loaded { r = $allocated1(...) | r = $allocated2(...) | $allocated3(?, ?, ?, &r) | $allocated4(?, ?, ?, &r)}
loaded -> closed { r.$close1(...) | $close2(r) | $close3(r) }
closed -> released { $release(r) | r.$releaseStream(...) }
closed -> end_of_scope { #end_scope(r) }
loaded -> ifblock { #ifblock(r, null, true) }
loaded -> end_of_scope { #end_scope(r) }

state start (start);
state loaded;
state released;
state closed;
state ifblock;
state end_of_scope (error);
var r;
start -> loaded { r = allocated1(...) | r = allocated2(...) | allocated3(?, ?, ?, &r) | allocated4(?, ?, ?, &r)}
loaded -> closed { r.close1(...) | close2(r) | close3(r) }
closed -> released { release(r) | r.$releaseStream(...) }
closed -> end_of_scope { #end_scope(r) }
loaded -> ifblock { #ifblock(r, null, true) }
loaded -> end_of_scope { #end_scope(r) }

state start (start);
state loaded;
state released;
state closed;
state ifblock;
state end_of_scope (error);
var r;
start -> loaded { r = $allocated1(...) | r = $allocated2(...) | $allocated3(?, ?, &r, ?) | $allocated4(?, ?, &r, ?) }
loaded -> closed { r.$close1(...) | $close2(r) | $close3(r) }
closed -> released { $release(r) | r.$releaseStream(...) }
closed -> end_of_scope { #end_scope(r) }
loaded -> ifblock { #ifblock(r, null, true) }
loaded -> end_of_scope { #end_scope(r) }

state start (start);
state loaded;
state released;
state closed;
state ifblock;
state end_of_scope (error);
var r;
start -> loaded { r = allocated1(...) | r = allocated2(...) | allocated3(?, ?, &r, ?) | allocated4(?, ?, &r, ?) }
loaded -> closed { r.close1(...) | close2(r) | close3(r) }
closed -> released { release(r) | r.$releaseStream(...) }
closed -> end_of_scope { #end_scope(r) }
loaded -> ifblock { #ifblock(r, null, true) }
loaded -> end_of_scope { #end_scope(r) }

state start (start);
state init;
state safe;
state error (error);

var c;

start -> init { c = $newconfiguration(...) }
init -> safe { c.$minimumTLSversion(...) }
init -> error { $session1(?, c, ...) }
init -> error { $session2(c,...) }

state start (start);
state init;
state safe;
state error (error);

var m;

start -> init { m = $newmanager1(...) | m = $newmanager2(...) }
init -> safe { m.$setSecurityPolicy(...) }
init -> error { m.$request(...) }

state start (start);
state init;
state safe;
state error (error);

var m;

start -> init { m = $newClient1(...) | m.$newClient2(...) }
init -> safe { m.$setPinningMode(...) }
init -> error { m.$request1(...) }

CharacterizationRule.StructuralMatch:
Function:
    name == "webView:didReceiveAuthenticationChallenge:completionHandler:"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name == "SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

FunctionCall fc:
    name == "setAutocorrectionType:"
    and arguments[0].constantValue matches "UITextAutocorrectionTypeNo|1"
    and instance is [FunctionCall:
        function is [Function getter:
            enclosingClass.fields contains [Field f:
                name endsWith getter.name
                and name startsWith "_"
            ]
        ]
    ]

FunctionCall fc:
    name == "setSecureTextEntry:"
    and arguments[0].constantValue matches "(?i)true|yes|1"
    and instance is [FunctionCall:
        function is [Function getter:
            enclosingClass.fields contains [Field f:
                name endsWith getter.name
                and name startsWith "_"
            ]
        ]
    ]

FunctionCall: function is [Function:
      name == "setHidden:"
    ]
    and arguments[0].constantValue matches "(?i)true|yes|1"
    /* where fields that are meant to remain hidden are normally configured */
    and enclosingFunction.name == "viewDidLoad"
    and instance is [FunctionCall:
        function is [Function getter:
            enclosingClass.fields contains [Field f:
                f.name endsWith getter.name
                and f.name startsWith "_"
                /* field is not later un-hidden */
                and not enclosingClass.functions contains [Function fun:
                    fun contains [FunctionCall:
                        function is [Function:
                            name == "setHidden:"
                        ]
                        and instance is [FunctionCall:
                            possibleTargets contains [Function getter2:
                                f.name endsWith getter2.name
                                and f.name startsWith "_"
                            ]
                        ]
                        and (arguments[0].constantValue is [String: matches "(?i)false|no|0"]
                        or arguments[0].constantValues contains [Number: == 0])
                    ]
                ]
            ]
        ]
    ]

FunctionCall: function is [Function:
      name == "setHidden:"
    ]
    and arguments[0].constantValue matches "(?i)true|yes|1"
    and enclosingFunction is [Function:
         name matches "applicationDidEnterBackground:|applicationWillResignActive:"
    ]
    and instance is [FunctionCall getter:
        instance.type.definition is [Class controller:
            fields contains [Field f:
                name endsWith getter.name
                and name startsWith "_"
            ]
        ]
    ]

FunctionCall: function is [Function:
      name == "setHidden:"
    ]
    and arguments[0].constantValue matches "(?i)true|yes|1"
    and enclosingFunction is [Function callback:
        callback.enclosingClass is [Class viewController:
            viewController.supers contains [Class: name == "UIViewController"]
            and viewController.functions contains [Function register:
                register contains [FunctionCall addObserver:
                    possibleTargets contains [Function:
                        name == "addObserver:selector:name:object:"
                    ]
                    and arguments[2] is [VariableAccess:
                        variable.name == "UIApplicationDidEnterBackgroundNotification"
                    ]
                    and arguments[1].constantValue is [String sel:
                        sel == callback.name
                    ]
                ]
            ]
        ]
    ]
    and instance is [FunctionCall getter:
        possibleTargets contains [Function:
            enclosingClass.fields contains [Field field:
                name endsWith getter.name
                and name startsWith "_"
            ]
        ]
    ]

Function:
    name matches "URLSession:didReceiveChallenge:completionHandler:"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name == "SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function:
    name matches "URLSession:task:didReceiveChallenge:completionHandler:"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name == "SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function:
    name matches "connection:didReceiveAuthenticationChallenge:|connection:willSendRequestForAuthenticationChallenge:"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name == "SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function f:
    name == "URLSession:dataTask:willCacheResponse:completionHandler:"
    and enclosingClass is [Class delegate:]
    and contains [FunctionPointerCall:
        (functionPointer is [VariableAccess:
            variable.name == "completionHandler"
        ]
        or functionPointer is [FieldAccess fa:
            field.name == "~lambda"
            and instance is [Dereference:
                expression is [VariableAccess:
                    variable.name == "completionHandler"
                ]
            ]
        ])
        and (
            /* either we find that the completionHandler is called with nil */
            arguments contains [Expression: constantValues contains [Null:]]
            /* or that its invoked with a variable that may contain nil as value */
            /* see bug 57773 */
            or arguments contains [VariableAccess:
                variable is [Variable:
                    uses contains [VariableAccess va:
                        enclosingStatement is [AssignmentStatement:
                            lhs is [VariableAccess va2: va2 is va]
                            and rhs.constantValues contains [Null:]
                        ]
                    ]
                ]
            ]
        )
    ]

Function f:
    name == "URLSession:dataTask:willCacheResponse:completionHandler:"
    and enclosingClass is [Class delegate:]
    and contains [FunctionPointerCall:
        (functionPointer is [VariableAccess:
            variable.name == "completionHandler"
        ]
        or functionPointer is [FieldAccess fa:
            field.name == "~lambda"
            and instance is [Dereference:
                expression is [VariableAccess:
                    variable.name == "completionHandler"
                ]
            ]
        ])
        and (
            /* either we find that the completionHandler is called with nil */
            arguments contains [Expression: constantValues contains [Null:]]
            /* or that its invoked with a variable that may contain nil as value */
            /* see bug 57773 */
            or arguments contains [VariableAccess:
                variable is [Variable:
                    /* see bug 58623 */
                    not enclosingFunction.null and
                    uses contains [VariableAccess va:
                        enclosingStatement is [AssignmentStatement:
                            lhs is [VariableAccess va2: va2 is va]
                            and rhs.constantValues contains [Null:]
                        ]
                    ]
                ]
            ]
        )
    ]

ReturnStatement rs:
    (
        /* either we find that the function returns nil */
        expression.constantValues contains [Null:]
        /* or that it returns a variable that may contain nil as value */
        /* see bug 57773 */
        or expression is [VariableAccess:
            variable is [Variable:
                uses contains [VariableAccess va:
                    enclosingStatement is [AssignmentStatement:
                        lhs is [VariableAccess va2: va2 is va]
                        and rhs.constantValues contains [Null:]
                    ]
                ]
            ]
        ]
    )
    and enclosingFunction is [Function:
        name == "connection:willCacheResponse:"
        and enclosingClass is [Class delegate:]
    ]

ReturnStatement rs:
    (
        /* either we find that the function returns nil */
        expression.constantValues contains [Null:]
        /* or that it returns a variable that may contain nil as value */
        /* see bug 57773 */
        or expression is [VariableAccess:
            variable is [Variable:
                /* see bug 58623 */
                not enclosingFunction.null and
                uses contains [VariableAccess va:
                    enclosingStatement is [AssignmentStatement:
                        lhs is [VariableAccess va2: va2 is va]
                        and rhs.constantValues contains [Null:]
                    ]
                ]
            ]
        ]
    )
    and enclosingFunction is [Function:
        name == "connection:willCacheResponse:"
        and enclosingClass is [Class delegate:]
    ]

Function:
    name == "webView:decidePolicyForNavigationAction:decisionHandler:"
    and enclosingClass is [Class delegate:]
    and contains [FunctionPointerCall:
        (functionPointer is [VariableAccess:
            variable.name == "decisionHandler"
        ]
        or functionPointer is [FieldAccess fa:
            field.name == "~lambda" and instance is [Dereference:
                expression is [VariableAccess:
                    variable.name == "decisionHandler"
                ]
            ]
        ])
        and arguments contains [VariableAccess:
            variable.name == "WKNavigationActionPolicyCancel"
        ]
    ]

Description.Explanation:
In practice, encryption with an RSA public key is usually combined with a padding scheme. A padding scheme can prevent attacks on RSA that only work when the encryption is performed without padding.

<b>Example 1:</b> The following code performs encryption using an RSA public key without using a padding scheme:
<pre>
+ (NSData *) encryptData:(NSData *) plaintextData withKey:(SecKeyRef *) publicKey {
    CFErrorRef error = nil;

    NSData *ciphertextData = (NSData*) CFBridgingRelease(
        SecKeyCreateEncryptedData(*publicKey,
                                  kSecKeyAlgorithmRSAEncryptionPKCS1,
                                  (__bridge CFDataRef) plaintextData,
                                  &amp;error));

    if (error) {
        // handle error ...
    }

    return ciphertextData;
}
</pre>

Description.Recommendations:
To use RSA securely, you must use OAEP (Optimal Asymmetric Encryption Padding) when performing encryption.

<b>Example 2:</b> The following code performs encryption with an RSA public key using OAEP padding:
<pre>
+ (NSData *) encryptData:(NSData *) plaintextData withKey:(SecKeyRef *) publicKey {
    CFErrorRef error = nil;

    NSData *ciphertextData = (NSData*) CFBridgingRelease(
        SecKeyCreateEncryptedData(*publicKey,
                                  kSecKeyAlgorithmRSAEncryptionOAEPSHA256,
                                  (__bridge CFDataRef) plaintextData,
                                  &amp;error));

    if (error) {
        // handle error ...
    }

    return ciphertextData;
}

</pre>

Description.Explanation:
The identified function writes data to the general pasteboard without excluding it from Universal Clipboard synchronization across devices via Handoff.

Content written to the general pasteboard is persistently stored across device restarts, app uninstalls, and app restores. Using the general pasteboard with the Universal Clipboard feature enabled increases the risk of stolen or modified pasteboard data as part of a Clipboard Hijacking attack by a malicious application running on another device.

Furthermore, because Universal Clipboard is compatible with devices running either iOS 10 and later or macOS Sierra and later, an increased threat is introduced by compatible devices running an older operating system that does not contain more recent privacy and security updates aimed to protect unauthorized clipboard access.

<b>Example 1:</b> In the following code, data is written to the general pasteboard setting the <code>items</code> property that shares pasteboard content between the user's devices by default via Universal Clipboard.

<pre>
...
UIPasteboard *pasteboard = [UIPasteboard generalPasteboard];
NSDictionary *items = @{
    UTTypePlainText : sensitiveDataString,
    UTTypePNG : [UIImage imageWithData:medicalImageData]
};
[pasteboard setItems: @[items]];
...
</pre>

<b>Example 2:</b> In the following code, data is written to the general pasteboard by calling the <code>setObjects:localOnly:expirationDate:</code> method with Universal Clipboard behavior explicitly enabled by setting the <code>localOnly</code> parameter to <code>NO</code>.

<pre>
...
UIPasteboard *pasteboard = [UIPasteboard generalPasteboard];
[pasteboard setObjects:@[sensitiveDataString, [UIImage imageWithData:medicalImageData]] 
            localOnly:NO 
            expirationDate:[NSDate distantFuture]];
...
</pre>

Description.Recommendations:
Apple Handoff's Universal Clipboard feature raises additional privacy concerns and security risks when sensitive information is written to the general pasteboard. It is best to avoid copying sensitive data to the general pasteboard altogether. However, if you must use the general pasteboard, disable the Universal Clipboard capability when copying sensitive data by using a <code>UIPasteboard</code> method that allows you to set the <code>localOnly</code> parameter or option to <code>YES</code>. This limits the accessibility of the pasteboard content to the current device only. It is also recommended to avoid storing data on the general pasteboard for longer than necessary by setting the <code>expirationDate</code> accordingly when writing data to the pasteboard.

<b>Example 3:</b> The following code demonstrates writing content to the general pasteboard by calling the <code>setItems:options:</code> method with the <code>localOnly</code> option set to <code>YES</code> and the <code>expirationDate</code> option set to remove the pasteboard content after two minutes.

<pre>
...
UIPasteboard *pasteboard = [UIPasteboard generalPasteboard];
NSDictionary *items = @{
    UTTypePlainText : sensitiveDataString,
    UTTypePNG : [UIImage imageWithData:medicalImageData]
};
NSDictionary *options = @{
    UIPasteboardOptionLocalOnly : @(YES),
    UIPasteboardOptionExpirationDate : [NSDate dateWithTimeIntervalSinceNow:120]
};
[pasteboard setItems: @[items] 
            options: options];
...
</pre>

<b>Example 4:</b> The following code demonstrates writing content to the general pasteboard by calling the <code>setObjects:localOnly:expirationDate:</code> method with the <code>localOnly</code> parameter set to <code>YES</code> and the <code>expirationDate</code> parameter set to remove the pasteboard content after two minutes.

<pre>
...
UIPasteboard *pasteboard = [UIPasteboard generalPasteboard];
[pasteboard setObjects:@[sensitiveDataString, [UIImage imageWithData:medicalImageData]] 
            localOnly:YES 
            expirationDate:[NSDate dateWithTimeIntervalSinceNow:120]];
...
</pre>

<b>Example 5:</b> The following code demonstrates writing content to the general pasteboard by calling the <code>setItemProviders(_:localOnly:expirationDate:)</code> method with the <code>localOnly</code> parameter set to <code>YES</code> and the <code>expirationDate</code> parameter set to remove the pasteboard content after two minutes.

<pre>
...
UIPasteboard *pasteboard = [UIPasteboard generalPasteboard];
NSItemProvider *itemProvider1 = [[NSItemProvider alloc] initWithObject:sensitiveDataString];
NSItemProvider *itemProvider2 = [[NSItemProvider alloc] initWithObject:[UIImage imageWithData:medicalImageData]];
[pasteboard setItemProviders:@[itemProvider1, itemProvider2] 
            localOnly:YES 
            expirationDate:[NSDate dateWithTimeIntervalSinceNow:120]];
...
</pre>

Description.Explanation:
An external information leak occurs when system data or debugging information leaves the program to a remote machine via a socket or network connection.

<Paragraph>
In this case, the data from <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/> leaves the program through <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>

<b>Example 1:</b> The following code leaks system information via an HTTP request:

<pre>
NSString *deviceName = [[UIDevice currentDevice] name];
NSString *baseUrl = @"http://myserver.com/?dev=";
NSString *urlString = [baseUrl stringByAppendingString:deviceName];
NSURL *url = [NSURL URLWithString:urlString];
NSURLRequest* request = [NSURLRequest requestWithURL:url cachePolicy:NSURLRequestUseProtocolCachePolicy timeoutInterval:60.0];
NSError *err = nil;
NSURLResponse* response = nil;
NSData *data = [NSURLConnection sendSynchronousRequest:request returningResponse:&amp;response error:&amp;err];
</pre>

This information can be exposed to a remote user. In some cases the error message tells the attacker precisely what sort of an attack the system will be vulnerable to. For example, a database error message can reveal that the application is vulnerable to a SQL injection attack. Other error messages can reveal more oblique clues about the system.

Privacy violations occur when:

1. Private user information enters the program.
<Paragraph>
In this case, the data comes from <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>.
</Paragraph>
2. The data is written to an external location, such as the console, file system, or network.
<Paragraph>
In this case, the data is passed to <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>
<b>Example 1:</b> The following code retrieves geolocation information from the mobile device and sends it to a server, while logging it to the device. Although many developers trust the log files as a safe storage location for any and all data, it should not be trusted implicitly, particularly when privacy is a concern.
<pre>
    locationManager = [[CLLocationManager alloc] init];
    locationManager.delegate = self;
    locationManager.desiredAccuracy = kCLLocationAccuracyBest;
    locationManager.distanceFilter = kCLDistanceFilterNone;
    [locationManager startUpdatingLocation];
    CLLocation *location = [locationManager location];
    // Configure the new event with information from the location
    CLLocationCoordinate2D coordinate = [location coordinate];

    NSString *latitude = [NSString stringWithFormat:@"%f", coordinate.latitude];
    NSString *longitude = [NSString stringWithFormat:@"%f", coordinate.longitude];

    NSLog(@"dLatitude : %@", latitude);
    NSLog(@"dLongitude : %@",longitude);

    NSString *urlWithParams = [NSString stringWithFormat:TOKEN_URL, latitude, longitude];

    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:urlWithParams]];
    [request setHTTPMethod:@"GET"];
    [[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Other areas of concern for maintaining the privacy of user data arise when a device has been lost or stolen. Once in possession of an iOS device, an attacker may access a great deal of data by connecting the device by USB. Files such as iOS Property Lists (plists) and SQLite databases are easily accessed and can disclose personal information. As a general rule, privacy related information should not be stored unprotected on the file system.

<b>Example 2:</b> The following code adds a password entry to the list of user defaults, and stores them immediately to a plist file.

<pre>
  NSUserDefaults *defaults = [NSUserDefaults standardUserDefaults];

  // Add password to user defaults
  [defaults setObject:@"Super Secret" forKey:@"passwd"];

  [defaults synchronize];
</pre>

Private data can enter a program in a variety of ways:

- Directly from the user in the form of a password or personal information.

- Accessed from a database or other data store by the application.

- Indirectly from a partner or other third party.

- Retrieved from mobile data stores including: address book, snapped photos, geolocation, configuration files (including plist), archived SMS messages, etc.

Sometimes data that is not labeled as private can have a privacy implication in a different context. For example, student identification numbers are usually not considered private because there is no explicit and publicly-available mapping to an individual student's personal information. However, if a school generates student identification based on student social security numbers, then the identification numbers should be considered private.

Security and privacy concerns often seem to compete with each other. From a security perspective, you should record all important operations so that any anomalous activity can later be identified. However, when private data is involved, this practice can create additional risk.

Although there are many ways in which private data can be handled unsafely, a common risk stems from misplaced trust. Programmers often trust the operating environment in which a program runs, and therefore believe that it is acceptable to store private information on the file system, in the registry, or in other locally-controlled resources. However, even if access to certain resources is restricted, it does not guarantee that the individuals who do have access can be trusted with certain data. For example, in 2004, an unscrupulous employee at AOL sold approximately 92 million private customer email addresses to a spammer marketing an offshore gambling web site [1].

In response to such high-profile exploits, the collection and management of private data is becoming increasingly regulated. Depending on its location, the type of business it conducts, and the nature of any private data it handles, an organization may be required to comply with one or more of the following federal and state regulations:

- Safe Harbor Privacy Framework [3]

- Gramm-Leach Bliley Act (GLBA) [4]

- Health Insurance Portability and Accountability Act (HIPAA) [5]

- California SB-1386 [6]

Despite these regulations, privacy violations continue to occur with alarming frequency.

Description.Recommendations:
In order to avoid this type of privacy violation, register any UIViewController classes that contain sensitive input controls as notification listeners for the <code>UIApplicationDidEnterBackgroundNotification</code> and <code>UIApplicationDidBecomeActiveNotification</code> notifications and implement the specified response selectors such that they hide sensitive fields on backgrounding and restore them on returning from the background:

<pre>
ViewController.h
...

@property (nonatomic, retain) IBOutlet UITextField *ssnField;

...

ViewController.m
...

    [[NSNotificationCenter defaultCenter] addObserver: self
                                             selector: @selector(applicationDidEnterBackground:)
                                                 name: UIApplicationDidEnterBackgroundNotification
                                               object: nil];

    [[NSNotificationCenter defaultCenter] addObserver: self
                                             selector: @selector(applicationDidBecomeActive:)
                                                 name: UIApplicationDidBecomeActiveNotification
                                               object: nil];

...

- (void)applicationDidEnterBackground:(UIApplication *)application {
    ...

    self.ssnField.hidden = YES;

    ...
}

- (void)applicationDidBecomeActive:(UIApplication *)application {
    ...

    self.ssnField.hidden = NO;

    ...
}

...
</pre>

Alternatively, setting the <code>secureTextEntry</code> property for the sensititve field to <code>YES</code> will both visually obscure input as it is entered as well as disable all other forms of caching.

When security and privacy demands clash, privacy should usually be given the higher priority. To accomplish this and still maintain required security information, cleanse any private information before it exits the program.

To enforce good privacy management, develop and strictly adhere to internal privacy guidelines. The guidelines should specifically describe how an application should handle private data. If your organization is regulated by federal or state law, ensure that your privacy guidelines are sufficiently strenuous to meet the legal requirements. Even if your organization is not regulated, you must protect private information or risk losing customer confidence.

The best policy with respect to private data is to minimize its exposure. Applications, processes, and employees should not be granted access to any private data unless the access is required for the tasks that they are to perform. Just as the principle of least privilege dictates that no operation should be performed with more than the necessary privileges, access to private data should be restricted to the smallest possible group.

Description.Explanation:
Path manipulation errors occur when the following two conditions are met:

1. An attacker can specify a path used in an operation on the file system.

2. By specifying the resource, the attacker gains a capability that would not otherwise be permitted.

For example, the program might give the attacker the ability to overwrite the specified file or run with a configuration controlled by the attacker.
<Paragraph>
In this case, the attacker can specify the value that enters the program at <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>, and this value is used to access a file system resource at <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>
<b>Example 1:</b> The following code uses input from the user to create a file path. The programmer has not considered the possibility that an attacker could provide a different file name which could cause the application to delete an unintended file.

<pre>
- (NSData*) testFileManager {

    NSString *rootfolder = @"/Documents/";
    NSString *filePath = [rootfolder stringByAppendingString:[fileName text]];

    NSFileManager *fm = [NSFileManager defaultManager];
    return [fm contentsAtPath:filePath];
}
</pre>

Description.Recommendations:
The root cause of XPath injection vulnerability is the ability of an attacker to change context in the XPath query, causing a value that the programmer intended to be interpreted as data to be interpreted as a command instead. When an XPath query is constructed, the programmer knows what should be interpreted as part of the command and what should be interpreted as data.

To prevent an attacker from violating the programmer's expectations, use an allow list to ensure that user-controlled values used in an XPath query are composed from only the expected set of characters and do not contain any XPath metacharacters given the context in which they are used. If a user-controlled value requires that it contain XPath metacharacters, use an appropriate encoding mechanism to remove their significance within the XPath query.

<b>Example 2:</b>
<pre>
...
    NSString *accountStr = account.text;
    if (accountStr != NULL) {
        NSInteger acct = [accountStr integerValue];
        if (acct != 0) {
           xmlXPathContextPtr xpathCtx;
           NSString *query = @"/accounts/account[actId='" + accountStr + @"']/email/text()";

           xpathCtx = xmlXPathNewContext(doc);

           /* Evaluate XPath expression */
           xmlChar *queryString = (xmlChar *)[query cStringUsingEncoding:NSUTF8StringEncoding];
           xpathObj = xmlXPathEvalExpression(queryString, xpathCtx);
...
</pre>

Description.Explanation:
XML External Entity (XXE) injection occurs when:

1. Data enters a program from an untrusted source.

2. The data is written to an &lt;ENTITY&gt; element of the DTD (Document Type Definition) in an XML document.

Applications typically use XML to store data or send messages. When used to store data, XML documents are often treated like databases and can potentially contain sensitive information. XML messages are often used in web services and can also be used to transmit sensitive information. XML messages can even be used to send authentication credentials.

The semantics of XML documents and messages can be altered if an attacker has the ability to write raw XML. In the most benign case, an attacker may be able to insert nested entity references and cause an XML parser consume ever increasing amounts of CPU resources. In more nefarious cases of XML external entity injection, an attacker may be able to add XML elements that expose the contents of local file system resources or reveal the existence of internal network resources.

<b>Example 1:</b>Here is some code that is vulnerable to XXE attacks:

<pre>
- (void) parseSomeXML: (NSString *) rawXml {

    BOOL success;
    NSData *rawXmlConvToData = [rawXml dataUsingEncoding:NSUTF8StringEncoding];
    NSXMLParser *myParser = [[NSXMLParser alloc] initWithData:rawXmlConvToData];
    [myParser setShouldResolveExternalEntities:YES];
    [myParser setDelegate:self];
}
</pre>

Assume an attacker is able to control <code>rawXml</code> such that the XML looks like the following:

<pre>
 &lt;?xml version="1.0" encoding="ISO-8859-1"?&gt;
 &lt;!DOCTYPE foo [
   &lt;!ELEMENT foo ANY &gt;
   &lt;!ENTITY xxe SYSTEM "file:///c:/boot.ini" &gt;]&gt;&lt;foo&gt;&amp;xxe;&lt;/foo&gt;
</pre>

When the XML is evaluated by the server, the &lt;foo&gt; element will contain the contents of the <code>boot.ini</code> file.

HTTP requests which utilize the <code>GET</code> method allow the URL and request parameters to be cached in the browser's URL cache, intermediary proxies, and server logs. This could expose sensitive information to individuals who do not have appropriate rights to the data.
<b>Example 1:</b> The following code makes an HTTP request using the GET HTTP method instead of POST.

<pre>
...
	NSString * const USER_URL = @"https://www.somesvr.com/someapp/user";
...
	NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:USER_URL]];
	[request setHTTPMethod:@"GET"];
...
</pre>

<b>Example 2:</b> If the application uses NSURLRequest then the default HTTP method is GET.

<pre>
...
	NSURLRequest *theRequest=[NSURLRequest requestWithURL:[NSURL URLWithString:@"http://www.apple.com/"]
                        cachePolicy:NSURLRequestUseProtocolCachePolicy
                    timeoutInterval:60.0];
	NSURLConnection *theConnection=[[NSURLConnection alloc] initWithRequest:theRequest delegate:self];
	if (theConnection) {
    	// Create the NSMutableData to hold the received data.
    	// receivedData is an instance variable declared elsewhere.
    		receivedData = [[NSMutableData data] retain];
	} else {
...
</pre>

Certain identified functions are known to blindly follow symbolic links. When this happens, your application will open, read, or write data to the file that the symbolic link points to instead of the representation of the symbolic link. An attacker may fool the application into writing to alternate or critical system files or provide compromised data to the application.

<b>Example 1:</b> The following code utilizes functions which follow symbolic links:

<pre>
...
	struct stat output;
	int ret = stat(aFilePath, &amp;output);
	// error handling omitted for this example
	struct timespec accessTime = output.st_atime;
...
</pre>

Description.Recommendations:
Use functions which do not follow symbolic links (such as fchown, lstat, or fstat).

<b>Example 2:</b> The following code utilizes functions which do NOT follow symbolic links:

<pre>
...
	struct stat output;
	int ret = lstat(aFilePath, &amp;output);
	// error handling omitted for this example
	struct timespec accessTime = output.st_atime;
...
</pre>

Description.Explanation:
Many APIs will minimize the risk of data loss by writing the entire file into a temporary file, then copy that file to the target destination. Make sure the identified method does not work on files or paths in public or temporary directories as an attacker may replace the temporary file the instant before it is written to the targeted file. This allows the attacker to control the content of files used by the application in public directories.

<b>Example 1:</b> The following code writes the active <code>transactionId</code> to a temporary file in the application Documents directory using a vulnerable method:

<pre>
...
//get the documents directory:
NSArray *paths = NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES);
NSString *documentsDirectory = [paths objectAtIndex:0];
//make a file name to write the data to using the documents directory:
NSString *fileName = [NSString stringWithFormat:@"%@/tmp_activeTrans.txt", documentsDirectory];
// write data to the file
NSString tId = @"TransactionId=12341234";
[tId writeToFile:fileName atomically:YES]
...
</pre>

Description.Recommendations:
To avoid this problem, work with file descriptors instead of file paths. Initialize an <code>NSFileHandle</code> object with the file descriptor and use <code>NSFileHandle</code> methods to write to the file.

<b>Example 2:</b> The following code uses file descriptors instead of direct file paths:

<pre>
...
//get the documents directory:
NSArray *paths = NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES);
NSString *documentsDirectory = [paths objectAtIndex:0];
//make a file name to write the data to using the documents directory:
NSString *fileName = [NSString stringWithFormat:@"%@/tmp_XXX_activeTrans.txt", documentsDirectory];
const char *cFileName = [fileName UTF8String];
// write data to the file
NSString *tId = @"TransactionId=12341234";
fd = mkstemp(cFileName);
NSFileHandle *myhandle = [[NSFileHandle alloc] initWithFileDescriptor:fd];
[myhandle writeData:[tId dataUsingEncoding:NSUTF8StringEncoding]];
...
</pre>

Description.Explanation:
When character sets are mismatched between the operating system and applications running on the operating system, unsupported characters passed to default API methods can be best-fit mapped to dangerous characters.

<b>Example 1:</b> In Objective-C, the following example converts an NSString object containing a UTF-8 character to ASCII data then back:

<pre>
...
unichar ellipsis = 0x2026;
NSString *myString = [NSString stringWithFormat:@"My Test String%C", ellipsis];
NSData *asciiData = [myString dataUsingEncoding:NSASCIIStringEncoding allowLossyConversion:YES];
NSString *asciiString = [[NSString alloc] initWithData:asciiData encoding:NSASCIIStringEncoding];
NSLog(@"Original: %@ (length %d)", myString, [myString length]);
NSLog(@"Best-fit-mapped: %@ (length %d)", asciiString, [asciiString length]);
// output:
// Original: My Test String... (length 15)
// Best-fit-mapped: My Test String... (length 17)
...
</pre>

If you look at the output carefully, the "..." character was translated to three consecutive periods. If you had sized your output buffer based on the input buffer your application could be vulnerable to buffer overflow. Other characters can get mapped from one character to two. The Greek "fi" character will get mapped to an "f" followed by an "i". By front loading the buffer with these characters an attacker gains complete control over the number of characters used to overflow the buffer.

Description.Recommendations:
Ensure that character best-fit-mapping is turned off and utilize a character set which supports all characters (such as UTF8).

<b>Example 2:</b> The following code disables best-fit mapping:

<pre>
...
unichar ellipsis = 0x2026;
NSString *myString = [NSString stringWithFormat:@"My Test String%C", ellipsis];
NSData *data = [myString dataUsingEncoding: NSUTF8StringEncoding allowLossyConversion:NO];
if (data != nil) {
    NSString *utf8String = [[NSString alloc] initWithData:data encoding: NSUTF8StringEncoding];
    NSLog(@"Original: %@ (length %d)", myString, [myString length]);
    NSLog(@"Best-fit-mapped: %@ (length %d)", asciiString, [asciiString length]);
} else {
    NSLog("Conversion error")
}
...
</pre>

Description.Explanation:
Memory leaks have two common and sometimes overlapping causes:

- Error conditions and other exceptional circumstances.

- Confusion over which part of the program is responsible for freeing the memory.
<Paragraph>
In this case, the memory allocated in <Replace key="FirstTraceLocation.file"/> on line <Replace key="FirstTraceLocation.line"/> is not freed in the object's <code>dealloc()</code> method.
</Paragraph>
Most memory leaks result in general software reliability problems, but if an attacker can intentionally trigger a memory leak, the attacker may be able to launch a denial of service attack (by crashing the program) or take advantage of other unexpected program behavior resulting from a low memory condition [1].

<b>Example 1:</b> The Objective-C object allocates memory in the <code>init()</code> method but fails to free it in the <code>deallocate()</code> method, resulting in a memory leak:

<pre>
- (void)init
{
    myVar = [NSString alloc] init];
    ...
}

- (void)dealloc
{
    [otherVar release];
}
</pre>

Description.Recommendations:
Ensure that the <code>release()</code> method is called on the member variable in the <code>dealloc()</code> method of the object.

<pre>
- (void)init
{
    myVar = [NSString alloc] init];
    ...
}

- (void)dealloc
{
    [myVar release];
    [otherVar release];
    [super dealloc];
}
</pre>

Alternatively, Automatic Reference Counting can be enabled for the project.

Description.Explanation:
All data sent over HTTP is sent in the clear and subject to compromise.

<b>Example 1:</b> The following example sends data over the HTTP protocol (versus HTTPS).

<pre>
NSString * const USER_URL = @"http://localhost:8080/igoat/user";
NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:USER_URL]];
[[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Description.Recommendations:
Use HTTPS to send data to the server.
<b>Example 2:</b> The following example sends data over the HTTPS protocol (versus HTTP).

<pre>
NSString * const USER_URL = @"https://localhost:8080/igoat/user";
NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:USER_URL]];
[[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Description.Explanation:
All data sent over HTTP is sent in the clear and subject to compromise.

<b>Example 1:</b> The following example sends data over the HTTP protocol (versus HTTPS).

<pre>
NSURL *url = [[NSURL alloc] initWithScheme:@"http" host:@"localhost:8080" path:@"/igoat/user"];
NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url];
[[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Description.Recommendations:
Use HTTPS to send data to the server.
<b>Example 2:</b> The following example sends data over the HTTPS protocol (versus HTTP).

<pre>
NSURL *url = [[NSURL alloc] initWithScheme:@"https" host:@"localhost:8080" path:@"/igoat/user"];
NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url];
[[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

When writing user supplied data to JSON, follow these guidelines:

1. Do not create JSON attributes with names that are derived from user input.

2. Ensure that all serialization to JSON is performed using a safe serialization function that delimits untrusted data within single or double quotes and escapes any special characters.

<b>Example 2:</b> The following Objective-C code implements the same functionality as that in <code>Example 1</code>, but instead uses <code>NSJSONSerialization.dataWithJSONObject:</code> rather than <code>NSString.stringWithFormat:</code> to serialize the data, therefore ensuring that any untrusted data is properly delimited and escaped:

<pre>
...

NSError *error;
NSData *jsonData;
NSString *jsonString;
NSDictionary *jsonDictionary = @{@"username": _usernameField.text,
                                @"password": _passwordField.text,
                                @"role": @"default"};

if ([NSJSONSerialization isValidJSONObject:jsonDictionary]) {
  jsonData = [NSJSONSerialization dataWithJSONObject:jsonDictionary options:NSJSONWritingPrettyPrinted error:&amp;error];

  if (jsonData != nil &amp;&amp; error == nil) {
    jsonString = [[NSString alloc] initWithData:jsonData encoding: NSUTF8StringEncoding];
  }
}
    </pre>

Description.Explanation:
Assigning <code>null</code> to password variables is never a good idea as it may allow attackers to bypass password verification or might indicate that resources are protected by an empty password.

<Paragraph>
In this case, a <code>null</code> password was found in the call to <Replace key="PrimaryCall.name" link="PrimaryLocation"/> in <Replace key="PrimaryLocation.file"/> on line <Replace key="PrimaryLocation.line"/>.
</Paragraph>

<b>Example 1:</b> The following code initializes a password variable to <code>null</code>, attempts to read a stored value for the password, and compares it against a user-supplied value.

<pre>
    ...
    NSString *stored_password = NULL;

    readPassword(stored_password);

    if(safe_strcmp(stored_password, user_password)) {
        // Access protected resources
        ...
    }
    ...
</pre>

If <code>readPassword()</code> fails to retrieve the stored password due to a database error or another problem, then an attacker could trivially bypass the password check by providing a <code>null</code> value for <code>user_password</code>.

Assigning <code>null</code> to password variables is never a good idea as it may allow attackers to bypass password verification or might indicate that resources are protected by an empty password.

<Paragraph>
In this case, a <code>null</code> password was found in the call to <Replace key="PrimaryCall.name" link="PrimaryLocation"/> in <Replace key="PrimaryLocation.file"/> on line <Replace key="PrimaryLocation.line"/>.
</Paragraph>

<b>Example 1:</b> The following code initializes a password variable to <code>null</code>, attempts to read a stored value for the password, and compares it against a user-supplied value.

<pre>
    ...
    NSString *stored_password = NULL;

    readPassword(stored_password);

    if(safe_strcmp(stored_password, user_password)) {
        // Access protected resources
        ...
    }
    ...
</pre>

If <code>readPassword()</code> fails to retrieve the stored password due to a database error or another problem, then an attacker could trivially bypass the password check by providing a <code>null</code> value for <code>user_password</code>.

In some libraries that involve SSL connections, the server certificate is not verified by default (or can be explicitly configured to do so). This is equivalent to trusting all certificates.

<b>Example 1:</b> This code configures <code>NSURLConnectionDelegate</code> to accept any HTTPS certificate:

<pre>
implementation NSURLRequest (IgnoreSSL)

+ (BOOL)allowsAnyHTTPSCertificateForHost:(NSString *)host
{
  return YES;
}

@end
</pre>

When trying to connect to an SSL-secured server using the implementation of <code>NSURLRequest</code> from <code>Example 1</code>, no warnings or errors will result if the requested server's certificate is self-signed (and therefore unverified). As a result, the application would now potentially leak sensitive user information over the broken SSL connection.

Description.Recommendations:
Do not forget server verification checks when making SSL connections. Depending on the library used, make sure to verify server identity and establish a secure SSL connection.

<b>Example 2:</b> This code demonstrates the default implementation for the NSURLRequest type such that requests will only accept verified HTTPS certificates:

<pre>
implementation NSURLRequest (IgnoreSSL)

+ (BOOL)allowsAnyHTTPSCertificateForHost:(NSString *)host
{
  return NO;
}

@end
</pre>

Description.Explanation:
There is a vulnerability in implementations of regular expression evaluators and related methods that can cause the thread to hang when evaluating regular expressions that contain a grouping expression that is itself repeated. Additionally, any regular expression that contains alternate subexpressions that overlap one another can also be exploited. This defect can be used to execute a Denial of Service (DoS) attack.
<b>Example 1:</b> If the following regular expressions are used in the identified vulnerable code a denial of service could occur:
<pre>
  (e+)+
  ([a-zA-Z]+)*
  (e|ee)+
</pre>

Example of problematic code relying on a flawed regular expressions:

<pre>
NSString *regex = @"^(e+)+$";
NSPredicate *pred = [NSPRedicate predicateWithFormat:@"SELF MATCHES %@", regex];
if ([pred evaluateWithObject:mystring]) {
  //do something
}
</pre>

Most regular expression parsers build Nondeterministic Finite Automaton (NFA) structures when evaluating regular expressions. The NFA tries all possible matches until a complete match is found. Given the previous example, if the attacker supplies the match string "eeeeZ" then there are 16 internal evaluations that the regex parser must go through to identify a match. If the attacker provides 16 "e"s ("eeeeeeeeeeeeeeeeZ") as the match string then the regex parser must go through 65536 (2^16) evaluations. The attacker may easily consume computing resources by increasing the number of consecutive match characters. There are no known regular expression implementations that are immune to this vulnerability. All platforms and languages are vulnerable to this attack.

Database access control errors occur when:

1.Data enters a program from an untrusted source.
<Paragraph>
In this case, the data enters at <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>.
</Paragraph>

2.The data is used to specify the value of a primary key in a SQL query.
<Paragraph>
In this case, the data is used by <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>

<b>Example 1:</b> The following code uses a parameterized statement, which escapes metacharacters and prevents SQL injection vulnerabilities, to construct and execute a SQL query that searches for an invoice matching the specified identifier. The identifier is selected from a list of all invoices associated with the current authenticated user.

<pre>
...

        NSManagedObjectContext *context = [appDelegate managedObjectContext];
        NSEntityDescription *entityDesc = [NSEntityDescription entityForName:@"Invoices" inManagedObjectContext:context];
        NSFetchRequest *request = [[NSFetchRequest alloc] init];
        [request setEntity:entityDesc];
        NSPredicate *pred = [NSPredicate predicateWithFormat:@"(id = %@)", invoiceId.text];
        [request setPredicate:pred];

        NSManagedObject *matches = nil;
        NSError *error;
        NSArray *objects = [context executeFetchRequest:request error:&amp;error];

        if ([objects count] == 0) {
                 status.text = @"No records found.";
        } else {
                matches = [objects objectAtIndex:0];
                invoiceReferenceNumber.text = [matches valueForKey:@"invRefNum"];
                orderNumber.text = [matches valueForKey:@"orderNumber"];
                status.text = [NSString stringWithFormat:@"%d records found", [objects count]];
        }
        [request release];
...
</pre>

The problem is that the developer has failed to consider all of the possible values of <code>id</code>. Although the interface generates a list of invoice identifiers that belong to the current user, an attacker might bypass this interface to request any desired invoice. Because the code in this example does not check to ensure that the user has permission to access the requested invoice, it will display any invoice, even if it does not belong to the current user.

Description.Recommendations:
Rather than relying on the presentation layer to restrict values submitted by the user, access control should be handled by the application and database layers. Under no circumstances should a user be allowed to retrieve or modify a row in the database without the appropriate permissions. Every query that accesses the database should enforce this policy, which can often be accomplished by simply including the current authenticated username as part of the query.

<b>Example 2:</b> The following code implements the same functionality as <code>Example 1</code> but imposes an additional constraint to verify that the invoice belongs to the currently authenticated user.

<pre>
...

	NSManagedObjectContext *context = [appDelegate managedObjectContext];
        NSEntityDescription *entityDesc = [NSEntityDescription entityForName:@"Invoices" inManagedObjectContext:context];
        NSFetchRequest *request = [[NSFetchRequest alloc] init];
        [request setEntity:entityDesc];
        NSPredicate *pred = [NSPredicate predicateWithFormat:@"(id = %@) AND (user = '%@')", invoiceId.text, user];
        [request setPredicate:pred];

        NSManagedObject *matches = nil;
        NSError *error;
        NSArray *objects = [context executeFetchRequest:request error:&amp;error];

        if ([objects count] == 0) {
                 status.text = @"No records found.";
        } else {
                matches = [objects objectAtIndex:0];
                invoiceReferenceNumber.text = [matches valueForKey:@"invRefNum"];
                orderNumber.text = [matches valueForKey:@"orderNumber"];
                status.text = [NSString stringWithFormat:@"%d records found", [objects count]];
        }
        [request release];
...
</pre>

Description.Explanation:
SMS-related operations should not be performed unless they are essential to the core functionality of an application. Malware written for mobile devices often abuses such functionality to steal money or data from the user.

<b>Example 1:</b> In following cases, the application sends an SMS message or precomposes and presents an SMS message to the user that he or she is prompted to send or cancel:

<pre>...
[[CTMessageCenter sharedMessageCenter] sendSMSWithText:@"Hello world!" serviceCenter:nil toAddress:@"+12345678910"];
...

// or

...
[[UIApplication sharedApplication] openURL:[NSURL URLWithString:@"sms:+12345678910"]];
...

// or

...
MFMessageComposeViewController *messageComposerVC = [[MFMessageComposeViewController alloc] init];

[messageComposerVC setMessageComposeDelegate:self];
[messageComposerVC setBody:@"Hello World!"];
[messageComposerVC setRecipients:[NSArray arrayWithObject:@"+12345678910"]];

[self presentViewController:messageComposerVC animated:YES completion:nil];
...</pre>

The program can potentially fail to release a system resource.
<Paragraph>
In this case, there are program paths on which the resource allocated in <Replace key="FirstTraceLocation.file"/> on line <Replace key="FirstTraceLocation.line"/> is not released.
</Paragraph>

Resource leaks have at least two common causes:

- Error conditions and other exceptional circumstances.

- Confusion over which part of the program is responsible for releasing the resource.

Most unreleased resource issues result in general software reliability problems. However, if an attacker can intentionally trigger a resource leak, the attacker may be able to launch a denial of service attack by depleting the resource pool.

<b>Example 1:</b> The following method never closes the stream that it reads from.

<pre>
...
CFIndex numBytes;
do {
    UInt8 buf[bufferSize];
    numBytes = CFReadStreamRead(readStream, buf, sizeof(buf));
    if( numBytes &gt; 0 ) {
        handleBytes(buf, numBytes);
    } else if( numBytes &lt; 0 ) {
        CFStreamError error = CFReadStreamGetError(readStream);
        reportError(error);
    }
} while( numBytes &gt; 0 );
...
</pre>

Resource leaks have at least two common causes:

- Error conditions and other exceptional circumstances.

- Confusion over which part of the program is responsible for releasing the resource.

Most unreleased resource issues result in general software reliability problems. However, if an attacker can intentionally trigger a resource leak, the attacker can launch a denial of service by depleting the resource pool.

<b>Example 1:</b> The following code establishes a lock before <code>performOperationInCriticalSection()</code> but never releases it.

<pre>
os_unfair_lock lock1 = OS_UNFAIR_LOCK_INIT;
os_unfair_lock_lock(&amp;lock1);
performOperationInCriticalSection();
</pre>

Description.Recommendations:
Always release the lock after a critical section.

<b>Example 2:</b> The following code always releases the lock.
<pre>
os_unfair_lock lock1 = OS_UNFAIR_LOCK_INIT;
os_unfair_lock_lock(&amp;lock1);
performOperationInCriticalSection();
os_unfair_lock_unlock(&amp;lock1);
</pre>

Description.Explanation:
Files saved to iOS's photo album are world-readable and can be accessed by any application on the device. This could allow an attacker to steal sensitive photos, such as those of checks used for mobile check deposits.

<b>Example 1:</b> The following code uses <code>UIImageWriteToSavedPhotosAlbum</code> to save images to the photo album:

<pre>
- (void) imagePickerController:(UIImagePickerController *)picker didFinishPickingMediaWithInfo:(NSDictionary *)info
{
	// Access the uncropped image from info dictionary
	UIImage *image = [info objectForKey:UIImagePickerControllerOriginalImage];

  // Save image
  UIImageWriteToSavedPhotosAlbum(image, self, @selector(image:didFinishSavingWithError:contextInfo:), nil);

	...
}
</pre>

Description.Recommendations:
Utilize the Data Protection API to provide stricter protection for any sensitive information.

<b>Example 2:</b> The following code uses the Data Protection components of <code>NSFileManager</code> and <code>NSData</code> to sufficiently encrypt images before saving them to the photo album:

<pre>
- (void) imagePickerController:(UIImagePickerController *)picker didFinishPickingMediaWithInfo:(NSDictionary *)info
{
	// Access the uncropped image from info dictionary
	UIImage *image = [info objectForKey:UIImagePickerControllerOriginalImage];

	// Save image
  NSError *error = nil;
	NSData *imgData = UIImageJPEGRepresentation(image, 1);
	NSString  *jpgPath = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/Financial.jpg"];
	[imgData writeToFile:jpgPath options:NSDataWritingFileProtectionComplete error:&amp;error];
	[[NSFileManager defaultManager] setAttributes:[NSDictionary dictionaryWithObject:NSFileProtectionComplete forKey:NSFileProtectionKey] ofItemAtPath:jpgPath error:&amp;error];

  ...
}
</pre>

Description.Explanation:
Cross-site scripting (XSS) vulnerabilities occur when:

1. Data enters a web or mobile application through an untrusted source. In the case of Inter-Component Communication XSS, the untrusted source is data received from other components that reside on the same system. In the mobile world, these are applications running on the same device. In the case of reflected XSS, the untrusted source is typically a web request, while in the case of Persistent (also known as stored) XSS it is typically a database or other back-end data store.

<Paragraph>
In this case, the data enters at <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>.
</Paragraph>
2. The data is included in dynamic content that is sent to a web user without validation.
<Paragraph>
In this case, the data is sent at <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>
The malicious content sent to the web browser often takes the form of a JavaScript segment, but can also include HTML, Flash or any other type of code that the browser executes. The variety of attacks based on XSS is almost limitless, but they commonly include transmitting private data such as cookies or other session information to the attacker, redirecting the victim to web content controlled by the attacker, or performing other malicious operations on the user's machine under the guise of the vulnerable site.

Some think that in the mobile environment, classic web application vulnerabilities, such as cross-site scripting, do not make sense -- why would the user attack themself? However, keep in mind that the essence of mobile platforms is applications that are downloaded from various sources and run alongside each other on the same device. The likelihood of running a piece of malware next to a banking application is high, which necessitates expanding the attack surface of mobile applications to include inter-process communication.

<b>Example 1:</b> The following code enables an application to load an html page within a WKWebView with data from a URL request that uses the application's custom URL scheme:

AppDelegate.m:
<pre>
...
@property (strong, nonatomic) NSString *webContentFromURL;
...
- (BOOL)application:(UIApplication *)application openURL:(NSURL *)url sourceApplication:(NSString *)sourceApplication annotation:(id)annotation {
  ...
  [self setWebContentFromURL:[url host]];
  ...
...
</pre>

ViewController.m
<pre>
...
@property (strong, nonatomic) WKWebView *webView;
...
AppDelegate *appDelegate = (AppDelegate *)[[UIApplication sharedApplication] delegate];
...
[_webView loadHTMLString:appDelegate.webContentFromURL] baseURL:nil];
...
</pre>

Because the string passed to loadHTMLString: is user-controllable and JavaScript is enabled by default within a WKWebView, the user can write arbitrary content (including executable scripts) to the WKWebView via requests that use app's custom URL scheme.

<b>Example 2:</b> The following code reads the contents of a UITextField and displays it to the user within a WKWebView:

<pre>
...
@property (strong, nonatomic) WKWebView *webView;
@property (strong, nonatomic) UITextField *inputTextField;
...
[_webView loadHTMLString:_inputTextField.text baseURL:nil];
...
</pre>

The code in this example operates without issues if the text within <code>inputTextField</code> contains only standard alphanumeric text. If the text within <code>inputTextField</code> includes metacharacters or source code, then the input may be executed as code by the web browser as it displays the HTTP response.

Initially this might not appear to be much of a vulnerability. After all, why would someone provide input that can cause malicious code to run on their own device? The real danger is that an attacker may use email or social engineering tricks to lure victims into performing such actions. When this is successful, the victims unwittingly reflect the malicious content through the vulnerable web application back to their own devices. This mechanism of exploiting vulnerable web applications is known as Reflected XSS.

<b>Example 3:</b> The following code segment queries a database for an employee with a given ID and outputs the value in the display content of a WKWebView.

<pre>
...
@property (strong, nonatomic) WKWebView *webView;
...
NSFetchRequest *fetchRequest = [[NSFetchRequest alloc] init];
NSEntityDescription *entity = [NSEntityDescription entityForName:@"Employee" inManagedObjectContext:context];
[fetchRequest setEntity:entity];

NSArray *fetchedObjects = [context executeFetchRequest:fetchRequest error:&amp;error];
for (NSManagedObject *info in fetchedObjects) {
  NSString msg = @"Hello, " + [info valueForKey:@"name"];
  [_webView loadHTMLString:msg baseURL:nil]
  ...
}
...
</pre>

As in <code>Example 2</code>, this code functions correctly when the values of <code>name</code> are well-behaved, but it does nothing to prevent exploits if they are not. Again, this code can appear less dangerous because the value of <code>name</code> is read from a database, whose contents are apparently managed by the application. However, if the value of <code>name</code> originates from user-supplied data, then the database can be a conduit for malicious content. Without proper input validation on all data stored in the database, an attacker may execute malicious commands in the user's web browser. This type of exploit, known as Persistent (or Stored) XSS, is particularly insidious because the indirection caused by the data store makes it difficult to identify the threat and increases the possibility that the attack might affect multiple users. XSS got its start in this form with web sites that offered a "guestbook" to visitors. Attackers would include JavaScript in their guestbook entries, and all subsequent visitors to the guestbook page would execute the malicious code.

As the examples demonstrate, XSS vulnerabilities are caused by code that includes unvalidated data in an HTTP response. There are three vectors by which an XSS attack can reach a victim:

- As in <code>Example 1</code>, a source outside the target application makes a URL request using the target application's custom URL scheme, and unvalidated data from the URL request subsequently read back into the application as trusted data and included in dynamic content.

- As in <code>Example 2</code>, data is read directly from a user-controllable UI component and reflected back in the HTTP response. Reflected XSS exploits occur when an attacker causes a user to supply dangerous content to a vulnerable web application, which is then reflected back to the user and executed by the web browser. The most common mechanism for delivering malicious content is to include it as a parameter in a URL that is posted publicly or emailed directly to victims. URLs constructed in this manner constitute the core of many phishing schemes, whereby an attacker convinces victims to visit a URL that refers to a vulnerable site. After the site reflects the attacker's content back to the user, the content is executed and proceeds to transfer private information, such as cookies that might include session information, from the user's machine to the attacker or perform other nefarious activities.

- As in <code>Example 3</code>, the application stores dangerous data in a database or other trusted data store. The dangerous data is subsequently read back into the application and included in dynamic content. Persistent XSS exploits occur when an attacker injects dangerous content into a data store that is later read and included in dynamic content. From an attacker's perspective, the optimal place to inject malicious content is in an area that is displayed to either many users or particularly interesting users. Interesting users typically have elevated privileges in the application or interact with sensitive data that is valuable to the attacker. If one of these users executes malicious content, the attacker may be able to perform privileged operations on behalf of the user or gain access to sensitive data belonging to the user.

Many modern programming languages allow dynamic interpretation of source instructions. This capability allows programmers to perform dynamic instructions based on input received from the user. Code injection vulnerabilities occur when the programmer incorrectly assumes that instructions supplied directly from the user will perform only innocent operations, such as performing simple calculations on active user objects or otherwise modifying the user's state. However, without proper validation, a user might specify operations the programmer does not intend.

<b>Example 1:</b> The following code uses input from a UITextField to dynamically change the background color of the content within a WKWebView:

<pre>
...
@property (strong, nonatomic) WKWebView *webView;
@property (strong, nonatomic) UITextField *inputTextField;
...
[_webView evaluateJavaScript:[NSString stringWithFormat:@"document.body.style.backgroundColor="%@";", _inputTextField.text] completionHandler:nil];
...
</pre>

The program behaves correctly when the UITextField input is a benign value, such as &quot;blue&quot;, in which case the <code>&lt;body&gt;</code> element within <code>webView</code> would be styled to have a blue background. However, if an attacker provides malicious input that is still valid, he or she may be able to execute arbitrary JavaScript code. For example, because JavaScript can access certain types of private information such as cookies, if an attacker were to specify &quot;white&quot;;document.body.innerHTML=document.cookie;&quot;&quot; as input to the UITextField, cookie information would be visibly written to the page. Such attacks are even more dangerous when the underlying language provides access to system resources or allows the execution of system commands, as in those scenarios injected code is executed with the full privilege of the parent process.

The public key infrastructure (PKI) is based on trusted Ceritficate Authorities (CAs), however the increasing number of compromised Certificate Authorities means their root certificates can no longer be trusted and therefore no certificates that are signed by this CA can either. Attackers in possession of these compromised certificates will be able to intercept all the SSL/TLS traffic trusting these CAs.

Certificate Authorities signatures are necessary for general purpose network communication tools such as browsers that connect to arbitrary network endpoints and have no advance knowledge of which CAs sign the SSL/TLS certificates for those endpoints. Mobile applications that connect to a limited number of backend servers can benefit from knowing a shortlist of trusted CAs that these servers may use in signing their certificates and &quot;pin&quot; these certificates/public keys in the applications so that trust is reduced to the certificates the application expects.

<b>Example 1:</b> The following example establishes an SSL/TLS connection using the default pre-loaded system CAs.
<pre>
NSString* requestString = @"https://myserver.org";
NSURL* requestUrl = [NSURL URLWithString:requestString];
NSURLRequest* request = [NSURLRequest requestWithURL:requestUrl
                                         cachePolicy:NSURLRequestReloadIgnoringLocalCacheData
                                     timeoutInterval:10.0f];
NSURLConnection* connection = [[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Since there is no <code>NSURLConnectionDelegate</code> methods defined to handle certificate verification, it will use the system ones that will trust all the CAs present in the iOS default keystore.

Description.Recommendations:
There are several possible solutions to reduce the level of trust on pre-loaded system certificates including:

- Custom trust anchors: Use a custom keystore that only contains the certificates you want to trust.
- Certificate pinning: Trust the default certificates but verify and enforce that the one used by your backend server is present in the certificate chain. As an alternative, public keys can be pinned instead.

<b>Example 2:</b> The following example establishes an SSL/TLS connection using a custom keystore containing only the expected certificates.
<pre>
NSString* requestString = @"https://myserver.org";
NSURL* requestUrl = [NSURL URLWithString:requestString];
NSURLRequest* request = [NSURLRequest requestWithURL:requestUrl
                                         cachePolicy:NSURLRequestReloadIgnoringLocalCacheData
                                     timeoutInterval:10.0f];
NSURLConnection* connection = [[NSURLConnection alloc] initWithRequest:request delegate:self];

- (void)connection:(NSURLConnection *)connection didReceiveAuthenticationChallenge:(NSURLAuthenticationChallenge *)challenge {

    ...
    // Get a reference to the certificate presented by the server
    SecTrustRef serverTrust = [[challenge protectionSpace] serverTrust];
    if(!(nil != serverTrust)) gotoFail();
    CFIndex count = SecTrustGetCertificateCount(serverTrust);
	OSStatus status = SecTrustEvaluate(serverTrust, NULL);
	if(!(errSecSuccess == status)) gotoFail(); 
    SecCertificateRef serverCertificate = SecTrustGetCertificateAtIndex(serverTrust, 0);
    if(!(nil != serverCertificate)) gotoFail();
    // Perform the certificate verification
    ...
}
</pre>

<b>NOTE: </b> Do not use the code in <code>Example 2</code> in any application because it leaves out the verification step for brevity.

In this case, the <code>NSURLConnection</code> delegate is implementing a callback method to handle authentication and it is extracting the server's certificate and verifying it.

Description.Explanation:
In some libraries that involve SSL/TLS connections, the server certificate is not verified by default (or can be explicitly configured to do so). This is equivalent to trusting all certificates.

<b>Example 1:</b> This code demonstrates configuring an NSURLConnectionDelegate so that it will accept any HTTPS certificates:

<pre>
@implementation MyURLConnectionDelegate
    ...
    - (BOOL)connection:(NSURLConnection *)connection canAuthenticateAgainstProtectionSpace:(NSURLProtectionSpace *)protectionSpace {
        return [protectionSpace.authenticationMethod isEqualToString:NSURLAuthenticationMethodServerTrust];
    }

    - (void)connection:(NSURLConnection *)connection didReceiveAuthenticationChallenge:(NSURLAuthenticationChallenge *)challenge {
        [challenge.sender useCredential:[NSURLCredential credentialForTrust:challenge.protectionSpace.serverTrust] forAuthenticationChallenge:challenge];
        [challenge.sender continueWithoutCredentialForAuthenticationChallenge:challenge];
    }
    ...
}
</pre>

When trying to connect to an SSL-secured server using the implementation of <code>NSURLConnectionDelegate</code> described in <code>Example 1</code>, no warnings or errors will result if the requested server's certificate is self-signed (and therefore unverified). As a result, the application would now potentially leak sensitive user information over the broken SSL connection.

<b>Example 2:</b> In an <code>NSURLSession</code> class, the SSL/TLS chain validation is handled by your app's authentication delegate method, but instead of providing credentials to authenticate the user (or your app) to the server, your app instead checks the credentials that the server provides during the SSL/TLS handshake, then tells the URL loading system whether it should accept or reject those credentials. The following code shows an <code>NSURLSessionDelgate</code> that just passes <code>proposedCredential</code> of the challenge received back as a credential for the session, effectively bypassing the server verification:

<pre>
@implementation MyURLSessionDelegate
    ...
    -(void)URLSession:(NSURLSession *)session didReceiveChallenge:(NSURLAuthenticationChallenge *)challenge completionHandler:(void (^)(NSURLSessionAuthChallengeDisposition disposition, NSURLCredential * credential)) completionHandler {
        ...
        NSURLCredential *cred = [challenge proposedCredential];
        completionHandler(NSURLSessionAuthChallengeUseCredential, cred);
        ...
    }
    ...
@end
</pre>

Description.Recommendations:
Fortify highly recommends forcing the client to use only the most secure protocols.

<b>Example 2:</b>
<pre>
NSURLSessionConfiguration *configuration = [NSURLSessionConfiguration ephemeralSessionConfiguration];
[configuration setTLSMinimumSupportedProtocol = kTLSProtocol12];
NSURLSession *mySession = [NSURLSession sessionWithConfiguration:configuration delegate:self delegateQueue:operationQueue];
</pre>

<code>Example 2</code> demonstrates how to enforce communication over the TLSv1.2 protocol.

Fortify highly recommends forcing the client to use only the most secure protocols.

<b>Example 2:</b>
<pre>
NSURLSessionConfiguration *configuration = [NSURLSessionConfiguration ephemeralSessionConfiguration];
[configuration setTLSMinimumSupportedProtocol = kTLSProtocol12];
NSURLSession *mySession = [NSURLSession sessionWithConfiguration:configuration delegate:self delegateQueue:operationQueue];
</pre>

<code>Example 2</code> demonstrates how to enforce communication over the TLSv1.2 protocol.

In order to prevent the caching of HTTP(S) responses, implement the <code>NSURLSessionDataDelegate URLSession:dataTask:willCacheResponse:completionHandler:</code> delegate method and call <code>completionHandler(nil)</code> when the response should not be cached.

<b>Example 1:</b> The following implementation of the <code>NSURLSessionDataDelegate URLSession:dataTask:willCacheResponse:completionHandler:</code> delegate method completely disables HTTP(S) response caching by always returning <code>nil</code>:

<pre>
    - (void)URLSession:(NSURLSession *)session dataTask:(NSURLSessionDataTask *)dataTask willCacheResponse:(NSCachedURLResponse *)proposedResponse completionHandler:(void (^)(NSCachedURLResponse * __nullable ))completionHandler {
        completionHandler(nil);
    }
</pre>

In order to prevent the caching of HTTP(S) responses, implement the <code>NSURLSessionDataDelegate URLSession:dataTask:willCacheResponse:completionHandler:</code> delegate method and call <code>completionHandler(nil)</code> when the response should not be cached.

<b>Example 1:</b> The following implementation of the <code>NSURLSessionDataDelegate URLSession:dataTask:willCacheResponse:completionHandler:</code> delegate method completely disables HTTP(S) response caching by always returning <code>nil</code>:

<pre>
    - (void)URLSession:(NSURLSession *)session dataTask:(NSURLSessionDataTask *)dataTask willCacheResponse:(NSCachedURLResponse *)proposedResponse completionHandler:(void (^)(NSCachedURLResponse * __nullable ))completionHandler {
        completionHandler(nil);
    }
</pre>

Description.Explanation:
When a third party application or <code>webview</code> uses a URL to communicate with your application, the receiving application should validate the calling URL before proceeding with further actions. The receiving application has the option to verify that it wants to open the calling URL using the <code>UIApplicationDelegate application:didFinishLaunchingWithOptions:</code> or <code>UIApplicationDelegate application:willFinishLaunchingWithOptions:</code> delegate methods.

<b>Example 1:</b> The following implementation of the <code>UIApplicationDelegate application:didFinishLaunchingWithOptions:</code> delegate method fails to validate the calling URL and always processes the untrusted URL:

<pre>
    - (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NS Dictionary *)launchOptions {
        return YES;
    }
</pre>

Description.Recommendations:
Best practices dictate that we should always validate the calling URL and verify it conforms to what your application expects, which may vary depending on the URL components and purpose.

<b>Example 2:</b> The following implementation of the <code>UIApplicationDelegate application:didFinishLaunchingWithOptions:</code> delegate method validates the calling URL before processing the untrusted URL:

<pre>
    - (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NS Dictionary *)launchOptions {
        if ([launchOptions objectForKey:UIApplicationLaunchOptionsURLKey] != nil) {
            NSURL *url = (NSURL *)[launchOptions valueForKey:UIApplicationLaunchOptionsURLKey];
            if ([url query] != nil) {
                NSString *theQuery = [[url query] stringByReplacingPercentEscapesUsingEncoding:NSUTF8StringEncoding];
                if (![self isValidQuery:theQuery]) {
                    return NO;
                }
                return YES;
            }
        } 
        return NO;
    }
</pre>

Description.Explanation:
When a third party application or <code>webview</code> uses a URL to communicate with your application, the receiving application should verify that the sender matches an allow list of applications that are expected to communicate with it. The receiving application has the option to verify the origin of the calling URL using the <code>UIApplicationDelegate application:openURL:options:</code> or <code>UIApplicationDelegate application:openURL:sourceApplication:annotation:</code> delegate methods.

<b>Example 1:</b> The following implementation of the <code>UIApplicationDelegate application:openURL:options:</code> delegate method fails to verify the sender of the IPC call and just processes the calling URL:

<pre>
    - (BOOL)application:(UIApplication *)app openURL:(NSURL *)url options:(NSDictionary&lt;NSString *,id&gt; *)options {
        NSString *theQuery = [[url query] stringByRemovingPercentEncoding:NSUTF8StringEncoding];
        NSArray *chunks = [theQuery componentsSeparatedByString:@"&amp;"];
        for (NSString* chunk in chunks) {
            NSArray *keyval = [chunk componentsSeparatedByString:@"="]; NSString *key = [keyval objectAtIndex:0];
            NSString *value = [keyval objectAtIndex:1];
            // Do something with your key and value
        }
        return YES;
    }
</pre>

Description.Recommendations:
Best practices dictate that we should always verify the sender of an IPC call and check it against a list of expected origins as a security-in-depth control.

<b>Example 2:</b> The following implementation of the <code>UIApplicationDelegate application:openURL:options:</code> delegate method verifies that the sender of the IPC call matches a list of expected origins:

<pre>
    - (BOOL)application:(UIApplication *)app openURL:(NSURL *)url options:(NSDictionary&lt;NSString *,id&gt; *)options {
        NSString *source = [options valueForKey:UIApplicationOpenURLOptionsSourceApplicationKey];
        if ([source isEqualToString:@"com.apple.mobilesafari"] or [source isEqualToString:@"com.acme.my.other.app"]) {
            NSString *theQuery = [[url query] stringByRemovingPercentEncoding:NSUTF8StringEncoding];
            NSArray *chunks = [theQuery componentsSeparatedByString:@"&amp;"];
            for (NSString* chunk in chunks) {
                NSArray *keyval = [chunk componentsSeparatedByString:@"="]; NSString *key = [keyval objectAtIndex:0];
                NSString *value = [keyval objectAtIndex:1];
                // Do something with your key and value
            }
            return YES;
        } else {
            return NO; // We don't want to be called from anywhere else.
        } 
    }
</pre>

When reviewing an application that contains one or more Insecure Storage: Lacking Keychain Protection issues, it is likely that one will determine that a given resource should have stricter protection. One should always use the strictest Keychain accessibility constant possible within the constraints of the given application's functionality.

<b>Example 2:</b> In the following example the Keychain item is protected at all times, except when the device is powered on and unlocked. In addition, it will require a passcode to be configured on the device:

<pre>
...
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    NSData *token = [@"secret" dataUsingEncoding:NSUTF8StringEncoding];

    // Configure KeyChain Item
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:(__bridge id)kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly forKey:(__bridge id) kSecAttrAccessible];

    OSStatus error = SecItemAdd((__bridge CFDictionaryRef)dict, NULL);
...
</pre>

When reviewing an application that contains one or more Insecure Storage: Insufficient Keychain Protection issues, one may determine that a given resource should have stricter protection. Any data assigned <code>kSecAttrAccessibleAfterFirstUnlock</code> will remain continuously accessible while the device is powered on after the user enters their passcode for the first time post-boot. One should always use the strictest Keychain accessibility constant possible within the constraints of the given application's functionality.

<b>Example 2:</b> In the following example the Keychain item is protected at all times, except when the device is powered on and unlocked. In addition, it will require a passcode to be configured on the device:

<pre>
...
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    NSData *token = [@"secret" dataUsingEncoding:NSUTF8StringEncoding];

    // Configure KeyChain Item
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:(__bridge id)kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly forKey:(__bridge id) kSecAttrAccessible];

    OSStatus error = SecItemAdd((__bridge CFDictionaryRef)dict, NULL);
...
</pre>

If the item stored in the Keychain is sensitive and private enough such that it should not be synchronized to iCloud or stored in unencrypted backups, specify an accessibility level containing the <code>ThisDeviceOnly</code> suffix which will ensure that the Keychain item will not be backed up to iCloud, will be backed up to iTunes only if using encrypted backups, and cannot be restored onto another device.

<b>Example 2:</b> In the following example the Keychain item is protected at all times, except when the device is powered on and unlocked. In addition, it will not be backed up to iCloud nor to unencrypted iTunes backups:

<pre>
...
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    NSData *token = [@"secret" dataUsingEncoding:NSUTF8StringEncoding];

    // Configure KeyChain Item
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:(__bridge id)kSecAttrAccessibleWhenUnlockedThisDeviceOnly forKey:(__bridge id) kSecAttrAccessible];

    OSStatus error = SecItemAdd((__bridge CFDictionaryRef)dict, NULL);
...
</pre>

For highly sensitive data set the <code>kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly</code> accessibility level which will enforce a passcode set on the device to successfully store the sensitive data in the Keychain. In addition, if the user later decides to remove the passcode, the class keys used to decrypt the item will be discarded, preventing the item from being decrypted by the application.

<b>Example 2:</b> In the following example the Keychain item is protected at all times, except when the device is powered on and unlocked. In addition, a passcode is required to be set on the device:

<pre>
...
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    NSData *token = [@"secret" dataUsingEncoding:NSUTF8StringEncoding];

    // Configure KeyChain Item
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:(__bridge id)kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly forKey:(__bridge id) kSecAttrAccessible];

    OSStatus error = SecItemAdd((__bridge CFDictionaryRef)dict, NULL);
...
</pre>

When storing sensitive data into the Keychain, always specify an accessibility level explicitly, so it is clear when the item should be made available.

<b>Example 2:</b> In the following example the Keychain item is stored by explicitly specifying the accessibility level to protect the item:

<pre>
...
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    NSData *token = [@"secret" dataUsingEncoding:NSUTF8StringEncoding];

    // Configure Keychain Item
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:(__bridge id)kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly forKey:(__bridge id) kSecAttrAccessible];

    OSStatus error = SecItemAdd((__bridge CFDictionaryRef)dict, NULL);
...
</pre>

If the application accepts sensitive data via the keyboard, you may want to prevent the use of third party keyboards with your application. This is possible using the <code>UIApplicationDelegate application:shouldAllowExtensionPointIdentifier:</code> delegate method.

<b>Example 1:</b> In the following example the application disables the usage of keyboard extensions when the app is in the foreground:

<pre>
- (BOOL)application:(UIApplication *)application shouldAllowExtensionPointIdentifier:(NSString *)extensionPointIdentifier {
    if ([extensionPointIdentifier isEqualToString:UIApplicationKeyboardExtensionPointIdentifier]) {
        return NO;
    }
    return YES;
}
</pre>

Description.Explanation:
The extension receives data from the host app in its view controller and fails to implement the <code>SLComposeServiceViewController isContentValid</code> to validate the untrusted data received before using it.

<b>Example 1:</b> The following extension view controller receives data from the host app but fails to implement a callback method to validate it:

<pre>
    #import &lt;MobileCoreServices/MobileCoreServices.h&gt;

    @interface ShareViewController : SLComposeServiceViewController
        ...
    @end

    @interface ShareViewController ()
        ...
    @end

    @implementation ShareViewController

    - (void)didSelectPost {
        NSExtensionItem *item = self.extensionContext.inputItems.firstObject;
        NSItemProvider *itemProvider = item.attachments.firstObject;
        ...
        // Use the received items
        ...
        [self.extensionContext completeRequestReturningItems:@[] completionHandler:nil];
    }

    ...

    @end
</pre>

Description.Recommendations:
Best practices dictate that we should always validate the arbitrary and untrusted data received from external applications. It is important to ensure that your extension performs correct validation in the <code>isContentValid</code> method of its view controller, particularly in share or action extensions, and that received data conforms to what the extension expects, which may vary depending on the extension purpose.

<b>Example 2:</b> The following extension view controller receives data from the host app but fails to implement the <code>SLComposeServiceViewController isContentValid</code> callback method to validate it:

<pre>
    #import &lt;MobileCoreServices/MobileCoreServices.h&gt;

    @interface ShareViewController : SLComposeServiceViewController
        ...
    @end

    @interface ShareViewController ()
        ...
    @end

    @implementation ShareViewController

    - (BOOL)isContentValid {
        // Performs validation here and return YES if data should be further processed.
        ...
    }

    - (void)didSelectPost {
        NSExtensionItem *item = self.extensionContext.inputItems.firstObject;
        NSItemProvider *itemProvider = item.attachments.firstObject;
        ...
        // Use the received items
        ...
        [self.extensionContext completeRequestReturningItems:@[] completionHandler:nil];
    }

    ...

    @end
</pre>

Description.Explanation:
Touch ID based authentication can be implemented in two different flavors: using the <code>LocalAuthentication</code> framework or using Touch ID based access controls in the Keychain service.

Although both of them should be strong enough for most applications, the <code>LocalAuthentication</code> approach has some characteristics that make it less suitable for high risk apps such as banking, medical, and insurance:

- <code>LocalAuthentication</code> is defined outside of the device's Secure Enclave which implies that their APIs can be hooked and modified on jailbroken devices.
- <code>LocalAuthentication</code> authenticates the user by evaluating the context policy which may only evaluate to <code>true</code> or <code>false</code>. This boolean evaluation implies that the application will not be able to know who is really being authenticated, it just knows that fingerprint that is registered with the device was used or not. In addition, fingerprints that could be registered in the future will also successfully evaluate to <code>true</code>.


<b>Example 1:</b> The following code uses the <code>LocalAuthentication</code> framework to perform user authentication:

<pre>
    ...
    LAContext *context = [[LAContext alloc] init];  
    NSError *error = nil;  
    NSString *reason = @"Please authenticate using the Touch ID sensor.";

    if ([context canEvaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics error:&amp;error]) {  
        [context evaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics
            localizedReason:reason
                reply:^(BOOL success, NSError *error) {
                    if (success) {
                        // Fingerprint was authenticated
                    } else {
                        // Fingerprint could not be authenticated
                    }
            }
        ];
    ...
</pre>

Description.Recommendations:
When dealing with highly-sensitive data, a stronger approach should be used. Keychain services can be used to store sensitive data and require the correct fingerprints to be used in order to retrieve the data. This approach is stronger due to the following reasons:

- The Keychain is defined within the device's Secure Enclave which is not directly accessible programmatically. Access to the Keychain has to go through the operating system and the "securityd" daemon.
- The Keychain item may establish an ACL policy (<code>kSecAccessControlTouchIDCurrentSet</code>) that requires the item to be retrieved with the exact same fingerprints that were used to store the item.

The <code>kSecAccessControlTouchIDCurrentSet</code> attribute (added in iOS 9) should be used to protect against fingerprints being added or removed from iOS.

This approach can be used to securely store the credentials or tokens to authenticate to a backend server but the final user authentication should be performed in the backend server for stronger security.

<b>Example 2:</b> The following code stores an item in the Keychain which will require the user to use one of the currently set fingerprints in order to retrieve the item later:

<pre>
    ...
    SecAccessControlRef sacRef = SecAccessControlCreateWithFlags(kCFAllocatorDefault,
                 kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly,
                 kSecAccessControlTouchIDCurrentSet, 
                 nil);
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:account forKey:(__bridge id)kSecAttrAccount];
    [dict setObject:service forKey:(__bridge id) kSecAttrService];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:sacRef forKey:(__bridge id)kSecAttrAccessControl];
    [dict setObject:@"Please authenticate using the Touch ID sensor." forKey:(__bridge id)kSecUseOperationPrompt];

    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        OSStatus status = SecItemAdd((__bridge CFDictionaryRef)dict, nil);
    });
    ...
</pre>

Description.Explanation:
Touch ID based authentication can be implemented using the Keychain services by storing an item in the Keychain and setting an access control which requires the user to use their fingerprint to retrieve the item at a later time. The following policies can be used to define how the user will be authenticated using his fingerprint: 

- <code>kSecAccessControlUserPresence</code>: Constraint to access with either Touch ID or passcode. Touch ID does not have to be available or enrolled. Item is still accessible by Touch ID even if fingerprints are added or removed.
- <code>kSecAccessControlTouchIDAny</code>: Constraint to access with Touch ID for any enrolled fingerprints. Item is not invalidated if fingerprints are added or removed.
- <code>kSecAccessControlTouchIDCurrentSet</code>: Constraint to access with Touch ID for currently enrolled fingerprints. Item is invalidated if fingerprints are added or removed.

When using Touch ID you should use the <code>kSecAccessControlTouchIDCurrentSet</code> attribute to protect against fingerprints being added or removed in the future.

<b>Example 1:</b> The following code uses the <code>kSecAccessControlTouchIDAny</code> constraint that allows any future-enrolled fingerprint to unlock the Keychain item:

<pre>
    ...
    SecAccessControlRef sacRef = SecAccessControlCreateWithFlags(kCFAllocatorDefault,
                 kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly,
                 kSecAccessControlTouchIDCurrentSet, 
                 nil);
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:account forKey:(__bridge id)kSecAttrAccount];
    [dict setObject:service forKey:(__bridge id) kSecAttrService];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:sacRef forKey:(__bridge id)kSecAttrAccessControl];
    [dict setObject:@"Please authenticate using the Touch ID sensor." forKey:(__bridge id)kSecUseOperationPrompt];

    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        OSStatus status = SecItemAdd((__bridge CFDictionaryRef)dict, nil);
    });
    ...
</pre>

Description.Recommendations:
When dealing with highly-sensitive data, the strongest access control should be used. If using Touch ID, make sure to use the <code>kSecAccessControlTouchIDCurrentSet</code> constraint to invalidate the Keychain item for removed fingerprints or for future-enrolled ones.

<b>Example 2:</b> The following code stores an item in the Keychain which will require the user to use one of the currently set fingerprints in order to retrieve the item later:

<pre>
    ...
    SecAccessControlRef sacRef = SecAccessControlCreateWithFlags(kCFAllocatorDefault,
                 kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly,
                 kSecAccessControlTouchIDCurrentSet, 
                 nil);
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:account forKey:(__bridge id)kSecAttrAccount];
    [dict setObject:service forKey:(__bridge id) kSecAttrService];
    [dict setObject:token forKey:(__bridge id)kSecValueData];
    ...
    [dict setObject:sacRef forKey:(__bridge id)kSecAttrAccessControl];
    [dict setObject:@"Please authenticate using the Touch ID sensor." forKey:(__bridge id)kSecUseOperationPrompt];

    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        OSStatus status = SecItemAdd((__bridge CFDictionaryRef)dict, nil);
    });
    ...
</pre>

Description.Explanation:
According to Apple's policy, the application should always explain to users why their fingerprints are required. Failing to do so may confuse the user or even get your app rejected from the AppStore.

<b>Example 1:</b> The following code uses Touch ID to authenticate the user but fails to provide a localized reason that explains why the authentication is required:

<pre>
    [context evaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics localizedReason:nil
        reply:^(BOOL success, NSError *error) {
            if (success) {
                NSLog(@"Auth was OK");
            } 
    }];
</pre>

Description.Recommendations:
When requesting the user to enter credentials in the form of passcode, username, and password or biometrical characteristics, always explain how the credentials will be used.

<b>Example 2:</b> The following code uses Touch ID to authenticate the user and provides a localized reason that explains why authentication is required:

<pre>
    [context evaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics localizedReason:NSLocalizedString(@"Decrypt secret with fingerprint", nil)
        reply:^(BOOL success, NSError *error) {
            if (success) {
                NSLog(@"Auth was OK");
            } 
    }];
</pre>

Description.Explanation:
The <code>Documents</code> directory is intended to store non-transient application data, such as user-created content or local information allowing the app to run in offline mode. If <code>UIFileSharingEnabled</code> is set in your application's <code>Info.plist</code> file, files here will be accessible via iTunes. When writing sensitive data to the <code>Documents</code> directory, the data may be exposed in unencrypted backups or through the iTunes interface.

<b>Example 1:</b> The following snippet of code writes the user password in clear text within the <code>Documents</code> directory:

<pre>
    ...
    NSString *docsDirectory = [NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES) objectAtIndex:0];
    NSString *passwd_path = [docsDirectory stringByAppendingPathComponent:@"passwords.txt"];

    NSString *password = [user password];
    [password writeToFile:passwd_path atomically:YES encoding:NSUTF8StringEncoding error:nil];
    ...
</pre>

Description.Recommendations:
If sensitive information needs to be stored on the device, use the Keychain service to store it securely.

<b>Example 2:</b> The following snippet of code writes the user password securely in the Keychain service:

<pre>
    ...
    NSMutableDictionary *dict = [NSMutableDictionary dictionary];
    [dict setObject:(__bridge id)kSecClassGenericPassword forKey:(__bridge id) kSecClass];
    [dict setObject:account forKey:(__bridge id)kSecAttrAccount];
    [dict setObject:service forKey:(__bridge id) kSecAttrService];
    [dict setObject:secret forKey:(__bridge id)kSecValueData];
    ...
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        OSStatus status = SecItemAdd((__bridge CFDictionaryRef)dict, nil);
    });
    ...
</pre>

Description.Explanation:
When creating an instance of <code>NSURLCredential</code> containing the user's credentials in the form or a username/password pair or a client certificate, a persistence attribute needs to be defined. The possible values are:

- <code>NSURLCredentialPersistenceNone</code>: Credential should not be stored.
- <code>NSURLCredentialPersistenceForSession</code>: Credential should be stored only for this session.
- <code>NSURLCredentialPersistencePermanent</code>: Credential should be stored in the Keychain.
- <code>NSURLCredentialPersistenceSynchronizable</code>: Credential should be stored permanently in the Keychain, and in addition should be distributed to other devices based on the owning AppleID.

Since <code>NSURLCredentialPersistenceSynchronizable</code> credentials are distributed to other devices and iCloud, failing to completely remove the credential from all places will leave instances that could be leaked.

<b>Example 1:</b> The following snippet of code creates a synchronizable credential, uses it and then removes it locally but fails to remove it from other devices and iCloud:

<pre>
    ...
    // Create the credential
	NSURLCredential *credential = [NSURLCredential credentialWithUser:user password:password persistence:NSURLCredentialPersistenceSynchronizable]; 
    NSURLCredentialStorage *shared = [NSURLCredentialStorage sharedCredentialStorage];
    [shared setDefaultCredential:credential forProtectionSpace:protectionSpace]; 

    // Use the credential as needed
    ...

    // Removes the credential
    [shared removeCredential:credential forProtectionSpace:protectionSpace];
    ...
</pre>

Description.Recommendations:
When removing a synchronizable credential, do not use the <code>NSURLCredentialStorage removeCredential:forProtectionSpace:</code> method which will only remove it from the local Keychain. Instead, use the <code>NSURLCredentialStorage removeCredential:forProtectionSpace:options:</code> and pass an options dictionary containing the <code>NSURLCredentialStorageRemoveSynchronizableCredentials</code> set to <code>YES</code>.

<b>Example 2:</b> The following snippet of code creates a synchronizable credential, uses it and then removes it locally and from all other devices and iCloud:

<pre>
    ...
    // Create the credential
	NSURLCredential *credential = [NSURLCredential credentialWithUser:user password:password persistence:NSURLCredentialPersistenceSynchronizable]; 
    NSURLCredentialStorage *shared = [NSURLCredentialStorage sharedCredentialStorage];
    [shared setDefaultCredential:credential forProtectionSpace:protectionSpace]; 

    // Use the credential as needed
    ...

    // Removes the credential
    NSDictionary *options = [NSDictionary dictionaryWithObjects:@[@YES] forKeys:@[NSURLCredentialStorageRemoveSynchronizableCredentials]]; 
	[shared removeCredential:credential forProtectionSpace:protectionSpace options:options]; 
    ...
</pre>

If there are privacy or security concerns for the application regarding the credentials being stored in Apple's cloud environment or being distributed to other devices linked to the user Apple ID, you can explicitly select a persistence option that prevents the cloud synchronization. Furthermore, if your application's privacy requirements are high, you should use <code>NSURLCredentialPersistenceNone</code> to prevent the storage of the credential altogether.

<b>Example 2:</b> The following snippet of code creates a credential that will not be stored nor distributed:

<pre>
    ...
    NSURLCredential *credential = [NSURLCredential credentialWithUser:user password:password persistence:NSURLCredentialPersistenceNone]; 
    NSURLCredentialStorage *shared = [NSURLCredentialStorage sharedCredentialStorage];
    [shared setDefaultCredential:credential forProtectionSpace:protectionSpace]; 
    ...
</pre>

Description.Explanation:
Unless the contents of the page are completely under your control, the user will be able to click on links that may be used by malicious attackers to initiate undesired actions.

As an example, your application may be showing a blog post, or tweet, that may contain links. The author of the post or tweet your user is visiting will be able to use any arbitrary links on their pages. If your users visit a malicious site and are fooled or automatically driven to click a link, an attacker may be able to initiate some potentially dangerous actions such as using special URL schemes to initiate FaceTime or telephone calls, send data or initiate actions in third party applications, etc. Note that even if you control the landing page, the user may end up navigating to different and untrusted sites.

<b>Example 1:</b> The following snippet of code uses a <code>webview</code> to load a site that may contain untrusted links but it does not specify a delegate capable of validating the requests initiated in this <code>webview</code>:

<pre>
    ...
    NSURL *webUrl = [[NSURL alloc] initWithString:@"https://some.site.com/"];
    NSURLRequest *webRequest = [[NSURLRequest alloc] initWithURL:webUrl];
    [webView loadRequest: webRequest];
</pre>

Description.Recommendations:
If you do not expect any navigation other than HTTP(S) in your <code>webview</code>, use a delegate that implements the <code>WKNavigationDelegate</code> protocol callback functions to allow or deny navigation requests.

<b>Example 2:</b> The following snippet of code uses a <code>webview</code> to load a site that may contain untrusted links and specifies a delegate to be used to manage the <code>webview</code> that validates the requests made from the <code>webview</code> before these are sent:

<pre>
@interface MyWebViewDelegate : UIResponder &lt;WKNavigationDelegate&gt;
    ...
@end
@implementation MyWebViewDelegate
    ...
    - (void)webView:(WKWebView *)webView
        decidePolicyForNavigationAction:(WKNavigationAction *)navigationAction
        decisionHandler:(void (^)(WKNavigationActionPolicy))decisionHandler {

        NSString *urlString = navigationAction.request.URL.absoluteString;
        if ([urlString hasPrefix:@"http"]) {
            decisionHandler(WKNavigationActionPolicyAllow);
        } else {
            decisionHandler(WKNavigationActionPolicyCancel);
        }
    }
@end

// Function loading the webview.
    ...
    NSURL *webUrl = [[NSURL alloc] initWithString:@"https://some.site.com/"];
    NSURLRequest *webRequest = [[NSURLRequest alloc] initWithURL:webUrl];
    [webView setNavigationDelegate: [[MyWebViewDelegate alloc] init]];
    [webView loadRequest:webRequest];
</pre>

Description.Explanation:
Unless the contents of the page are completely under your control, the user will be able to click on links that could be used by malicious attackers to initiate automatic telephone or FaceTime calls.

As an example, your application may be showing a blog post, or tweet, that may contain links. The author of the post or tweet your user is visiting will be able to use any arbitrary links on their pages. If your users visit a malicious site and are fooled, or automatically driven to click a link, an attacker may be able to initiate automatic FaceTime or telephone calls and block the device for a few seconds to prevent the user from cancelling the call. Note that even if you control the landing page, the user may end up navigating to different and untrusted sites.

<b>Example 1:</b> The following snippet of code uses a <code>webview</code> to load a site that may contain untrusted links but it does not specify a delegate capable of validating the requests initiated in this <code>webview</code>:

<pre>
    ...
    NSURL *webUrl = [[NSURL alloc] initWithString:@"https://some.site.com/"];
    NSURLRequest *webRequest = [[NSURLRequest alloc] initWithURL:webUrl];
    [_webView loadRequest:webRequest];
    ...
</pre>

Description.Recommendations:
Best practices dictate that, if you do not expect any navigation other than HTTP(S) in your <code>webview</code>, you should use a delegate that implements the <code>UIWebViewDelegate.webView:shouldStartLoadWithRequest:navigationType:</code> or <code>WebKit.WKNavigationDelegate.webView:decidePolicyForNavigationAction:decisionHandler:</code> callback which will be called before initiating any requests for the <code>webview</code>.

<b>Example 2:</b> The following snippet of code uses a <code>UIKit.UIWebView</code> to load a site that may contain untrusted links. The example specifies a <code>UIWebViewDelegate</code> that validates the requests made from the <code>webview</code> before they are sent:

<pre>
@interface MyWebViewDelegate : UIResponder &lt;UIWebViewDelegate&gt;
    ...
@end
@implementation MyWebViewDelegate
...
- (BOOL)webView:(UIWebView *)webView shouldStartLoadWithRequest:(NSURLRequest *)request navigationType:(UIWebViewNavigationType)navigationType {
    ...
    NSString *URLString = [[request URL] absoluteString];
    if ([URLString hasPrefix:@"http"]) {
       return YES;
    } else {
       return NO;
    }
    ...
}
...
@end

// Function loading the webview.

    ...
    NSURL *webUrl = [[NSURL alloc] initWithString:@"https://some.site.com/"];
    NSURLRequest *webRequest = [[NSURLRequest alloc] initWithURL:webUrl];
    _webView.delegate = [[MyWebViewDelegate alloc] init];
    [_webView loadRequest:webRequest];
    ...
</pre>

<b>Example 3:</b> The following snippet of code uses a <code>WebKit.WKWebView</code> to load a site that may contain untrusted links. The example specifies a <code>WKNavigationDelegate</code> that validates the requests made from the <code>webview</code> before they are sent:

<pre>
@interface MyWebViewDelegate : UIResponder &lt;WKNavigationDelegate, WKUIDelegate&gt;
    ...
@end

@implementation MyWebViewDelegate
...
- (void)webView:(WKWebView *)webView decidePolicyForNavigationAction:(WKNavigationAction *)navigationAction decisionHandler:(void (^)(WKNavigationActionPolicy))decisionHandler {
    ...
    NSURL *url = navigationAction.request.URL;
    NSString *URLString = [url absoluteString];
    if ([URLString hasPrefix:@"http"]) {
        decisionHandler(WKNavigationActionPolicyAllow);
    } else {
        decisionHandler(WKNavigationActionPolicyCancel);
    }
    ...
}

- (WKWebView *)webView:(WKWebView *)webView createWebViewWithConfiguration:(WKWebViewConfiguration *)configuration forNavigationAction:(WKNavigationAction *)navigationAction windowFeatures:(WKWindowFeatures *)windowFeatures {

    UIApplication *app = [UIApplication sharedApplication];
    NSURL         *url = navigationAction.request.URL;

    if (!navigationAction.targetFrame) {
        if ([app canOpenURL:url]) {
            [app openURL:url];
        }
    }
    ...
}
...
@end
</pre>

Description.Explanation:
Leaks of private health information occur when:

1. User's health information enters the program.
<Paragraph>
In this case, the data comes from <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>.
</Paragraph>
2. The data is written to an external location, such as the console, file system, or network.
<Paragraph>
In this case, the data is passed to <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>

<b>Example 1:</b> The following code retrieves the user blood type from the HealthKit store and sends it to a server, while logging it to the device. Although many developers trust the log files as a safe storage location for any and all data, it should not be trusted implicitly, particularly when privacy is a concern.
<pre>
    ...
    HKHealthStore *healthStore = [[HKHealthStore alloc] init];
    HKBloodTypeObject *blood = [healthStore bloodTypeWithError:nil];

    NSLog(@"%@", [blood bloodType]);

    NSString *urlWithParams = [NSString stringWithFormat:TOKEN_URL, [blood bloodType]];

    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:urlWithParams]];
    [request setHTTPMethod:@"GET"];
    [[NSURLConnection alloc] initWithRequest:request delegate:self];
    ...
</pre>

Note: The Apple Logging API, which is at a lower level than the <code>NSLog</code> function, allows a developer to create an app which may read all logs on the device (even when they don't own the other apps).

Other areas of concern for maintaining the privacy of user data arise when a device has been lost or stolen. Once in possession of an iOS device, an attacker may access a great deal of data by connecting the device by USB. Files such as iOS Property Lists (plists) and SQLite databases are easily accessed and can disclose personal information. As a general rule, private health details should not be stored unprotected on the file system.

<b>Example 2:</b> The following code adds the user's blood type to the list of user defaults, and stores them immediately to a plist file.

<pre>
    ...
    HKHealthStore *healthStore = [[HKHealthStore alloc] init];
    HKBloodTypeObject *blood = [healthStore bloodTypeWithError:nil];

    // Add blood type to user defaults
    [defaults setObject:[blood bloodType] forKey:@"bloodType"];

    [defaults synchronize];
    ...
</pre>

In response to private data being mishandled, the collection and management of private data is becoming increasingly regulated. In regards to health information, an organization may be required to comply with one or more of the following federal and state regulations:

- Safe Harbor Privacy Framework [2]

- Gramm-Leach Bliley Act (GLBA) [3]

- Health Insurance Portability and Accountability Act (HIPAA) [4]

- California SB-1386 [5]

Despite these regulations, privacy violations continue to occur with alarming frequency.

Description.Recommendations:
To prevent predicate injections, do not let users control the predicate or any component directly after an operator that accepts wildcards (for example: <code>LIKE</code>, <code>CONTAINS</code>, or <code>MATCHES</code>) or imply a wildcard (for example: <code>BEGINSWITH</code> and <code>ENDSWITH</code>). Always review that the used operators make sense in the context of the predicate and avoid broad matching operators such as those mentioned previously dealing with security sensitive operations.

In addition, it is a better approach to build the predicate using <code>NSComparisonPredicate</code> and <code>NSCompoundPredicate</code> to reduce the ability of the user to modify other parts of the query.

<b>Example 2:</b> The following example uses a comparison predicate and a sanitization function to prevent predicate injection:

<pre>
NSExpression *deptExpression = [NSExpression expressionForKeyPath:@"departmentName"];
NSExpression *searchExpression = [NSExpression expressionForConstantValue:[self clean: searchTerm]];

NSPredicate *fetchPredicate = [NSComparisonPredicate predicateWithLeftExpression:deptExpression rightExpression:searchExpression modifier:NSDirectPredicateModifier type:NSLikePredicateOperatorType :0];
</pre>

Do not allow local files to run scripts within the context of your application. When there is absolutely no other choice, verify that the file has the correct permissions in order to ensure that the file cannot be modified by an attacker, and preferably have some way to verify that the file is only performing a subset of operations.

When using <code>UIKit.UIWebView</code>, use the <code>loadHTMLString(_:baseURL:)</code> method instead of <code>loadRequest(_:)</code> to avoid the file from being loaded in the privileged origin. Make sure to specify a non <code>nil</code>, non <code>file://</code> base URL.

<b>Example 2:</b> The following code uses <code>UIWebView.loadHTMLString(_:baseURL:)</code> to securely load a local file by setting a different origin from <code>file://</code>:

<pre>
...
NSString *HTML = [[NSBundle mainBundle] pathForResource: filename ofType: extension];
NSString *contents = [[NSString alloc] initWithContentsOfFile: HTML encoding:NSUTF8StringEncoding error:&amp;error;];
NSURL *baseUrl = [NSURL URLWithString:@"http://www.mysite.com"];
[webView loadHTMLString:contents baseURL: baseUrl];
...
</pre>

Alternatively, use <code>WebKit.WKWebView</code> instead of <code>UIKit.UIWebView</code> which is protected against file-based cross-zone scripting.

As an additional protection, disable the use of JavaScript in the WebView if possible. This would limit the scope of what an attacker may be able to run within the context of your application.

Description.Explanation:
Before creating a server trust credential, it is the responsibility of the delegate of an <code>NSURLConnection</code> object, an <code>NSURLSession</code> object or an <code>NSURLDownload</code> object to evaluate the trust chain. 

<b>Example 1:</b> The following code initializes an <code>NSURLCredential</code> using a non-evaluated server trust:
<pre>
-(void)URLSession:(NSURLSession *)session didReceiveChallenge:(NSURLAuthenticationChallenge *)challenge completionHandler:(void (^)(NSURLSessionAuthChallengeDisposition disposition, NSURLCredential * credential)) completionHandler {
        ...
        [challenge.sender useCredential:[NSURLCredential credentialForTrust: challenge.protectionSpace.serverTrust] forAuthenticationChallenge:challenge];
        ...
}
</pre>

Description.Recommendations:
Before creating the server trust credential, call <code>SecTrustEvaluate(_:_:)</code>, passing it the trust obtained from the <code>serverTrust()</code> method of the server's <code>NSURLProtectionSpace</code> object. If the trust is invalid, the authentication challenge should be canceled calling the <code>cancel(_:)</code> method.

<b>Example 2:</b> The following code evaluates the server trust before initializing the credential object:
<pre>
-(void)URLSession:(NSURLSession *)session didReceiveChallenge:(NSURLAuthenticationChallenge *)challenge completionHandler:(void (^)(NSURLSessionAuthChallengeDisposition disposition, NSURLCredential * credential)) completionHandler {
        ...
        SecTrustRef trust = [[challenge protectionSpace] serverTrust];
        ...
        SecTrustResultType result;
        OSStatus trustEvalStatus = SecTrustEvaluate(trustRef, &amp;result);
        if (trustEvalStatus == errSecSuccess) {
            if (result == kSecTrustResultProceed || result == kSecTrustResultUnspecified) {
                // evaluation OK
                [challenge.sender useCredential:[NSURLCredential credentialForTrust: challenge.protectionSpace.serverTrust] forAuthenticationChallenge:challenge];
            } 
            else {
                // evaluation failed 
                // ask user to add certificate to keychain
            }
        } 
        else {
            // evaluation failed - cancel authentication
            [[challenge sender] cancelAuthenticationChallenge:challenge];
        }
    }
    ...
}
</pre>

Description.Explanation:
The application implements the <code>NSURLConnection</code> or <code>NSURLSession</code> callbacks to handle authentication requests. Forgetting to ensure that the authentication request comes from the expected host would result in credentials being sent to every URL the application loads. In addition, failing to check that the credentials can be sent securely would result in credentials being stolen.

<b>Example 1:</b> The following application sends user credentials to any host asking for authentication:

<pre>
- (void)URLSession:(NSURLSession *)session didReceiveChallenge:(NS URLAuthenticationChallenge *)challenge completionHandler:(void (^)(NS URLSessionAuthChallengeDisposition, NSURLCredential *))completionHandler { 
    NSString *user = [self getUser]; 
    NSString *pass = [self getPassword]; 

    NSURLCredential *cred = [NSURLCredential credentialWithUser:user 
    password:pass persistence:NSURLCredentialPersistenceForSession]; 
    completionHandler(NSURLSessionAuthChallengeUseCredential, credential);
} 
</pre>

Description.Recommendations:
Before sending any credentials, verify the application is talking to the expected server and that the credentials can be sent securely.

<b>Example 2:</b> The following example shows how to check for the protection space host and whether the credentials can be sent securely.

<pre>
- (void)URLSession:(NSURLSession *)session didReceiveChallenge:(NS URLAuthenticationChallenge *)challenge completionHandler:(void (^)(NS URLSessionAuthChallengeDisposition, NSURLCredential *))completionHandler { 
    NSString *user = [self getUser]; 
    NSString *pass = [self getPassword]; 

    NSURLProtectionSpace *space = [challenge protectionSpace]; 
    if ([space receivesCredentialSecurely] == YES &amp;&amp; [[space host] isEqualToString:@"myhost.com"] &amp;&amp; [[space authenticationMethod] isEqualToString:NSURLAuthenticationMethodHTTPBasic]) { 
        NSURLCredential *credential = [NSURLCredential credentialWithUser:user 
        password:pass persistence:NSURLCredentialPersistenceForSession]; 
        completionHandler(NSURLSessionAuthChallengeUseCredential, credential); 
    } 
} 
</pre>

Description.Explanation:
Before creating a server trust credential, it is the responsibility of the delegate of an <code>NSURLConnection</code> object, <code>NSURLSession</code> object or an <code>NSURLDownload</code> object to evaluate the server trust. In order to evaluate the server trust, the <code>SecTrustEvaluate(_:_:)</code> method should be called with the trust obtained from the <code>serverTrust</code> method of the server's <code>NSURLProtectionSpace</code> object. 

The <code>SecTrustEvaluate(_:_:)</code> method returns two different values:

- The returned <code>OSStatus</code> value represents the result code.
- The object pointed by the second argument represents the result type of the evaluation.

If the trust is invalid, the authentication challenge should be canceled with <code>cancel(_:)</code>.

<b>Example 1:</b> In the following example, the server trust is evaluated but the received credentials are used without checking the result of this evaluation:

<pre>
SecTrustRef trust = [[challenge protectionSpace] serverTrust];
SecTrustResultType result = kSecTrustResultInvalid;
OSStatus status = SecTrustEvaluate(trust, &amp;result);
completionHandler(NSURLSessionAuthChallengeUseCredential, [challenge proposedCredential]);
</pre>

Description.Recommendations:
Before using the server trust to authenticate the server, always evaluate the certificate chain present on its server trust object by calling <code>SecTrustEvaluate(_:_:)</code>. Make sure you verify the results of this evaluation before trusting the server.

<b>Example 2:</b> In the following example, the server trust is evaluated and the results of this evaluation are checked before trusting the server. In particular, the code checks that there were no errors during the evaluation and that the result is either <code>proceed</code> (the user indicated that you may trust the certificate for the purposes designated in the specified policies) or <code>unspecified</code> (the user did not specify a trust setting).

<pre>
SecTrustResultType trustResult = kSecTrustResultInvalid;
OSStatus status = SecTrustEvaluate(trust, &amp;trustResult);
If (status == noErr &amp;&amp; (kSecTrustResultProceed == trustResult || kSecTrustResultUnspecified == trustResult)) {
	completionHandler(NSURLSessionAuthChallengeUseCredential, [challenge proposedCredential]);
}
</pre>

Description.Explanation:
Privacy violations occur when:

1. Private user information enters the program.
2. The data is written to an external location, such as the console, file system, or network.

<b>Example 1:</b> The following code retrieves geolocation information from the mobile device and sends it to a server, while logging it to the device. Although many developers trust the log files as a safe storage location for any and all data, it should not be trusted implicitly, particularly when privacy is a concern.
<pre>
    locationManager = [[CLLocationManager alloc] init];
    locationManager.delegate = self;
    locationManager.desiredAccuracy = kCLLocationAccuracyBest;
    locationManager.distanceFilter = kCLDistanceFilterNone;
    [locationManager startUpdatingLocation];
    CLLocation *location = [locationManager location];
    // Configure the new event with information from the location
    CLLocationCoordinate2D coordinate = [location coordinate];

    NSString *latitude = [NSString stringWithFormat:@"%f", coordinate.latitude];
    NSString *longitude = [NSString stringWithFormat:@"%f", coordinate.longitude];

    NSLog(@"dLatitude : %@", latitude);
    NSLog(@"dLongitude : %@",longitude);

    NSString *urlWithParams = [NSString stringWithFormat:TOKEN_URL, latitude, longitude];

    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:urlWithParams]];
    [request setHTTPMethod:@"GET"];
    [[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Other areas of concern for maintaining the privacy of user data arise when a device has been lost or stolen. Once in possession of an iOS device, an attacker may access a great deal of data by connecting the device by USB. Files such as iOS Property Lists (plists) and SQLite databases are easily accessed and can disclose personal information. As a general rule, privacy related information should not be stored unprotected on the file system.

<b>Example 2:</b> The following code adds a password entry to the list of user defaults, and stores them immediately to a plist file.

<pre>
  NSUserDefaults *defaults = [NSUserDefaults standardUserDefaults];

  // Add password to user defaults
  [defaults setObject:@"Super Secret" forKey:@"passwd"];

  [defaults synchronize];
</pre>

Private data can enter a program in a variety of ways:

- Directly from the user in the form of a password or personal information.

- Accessed from a database or other data store by the application.

- Indirectly from a partner or other third party.

- Retrieved from mobile data stores including: address book, snapped photos, geolocation, configuration files (including plist), archived SMS messages, etc.

Sometimes data that is not labeled as private can have a privacy implication in a different context. For example, student identification numbers are usually not considered private because there is no explicit and publicly-available mapping to an individual student's personal information. However, if a school generates student identification based on student social security numbers, then the identification numbers should be considered private.

Security and privacy concerns often seem to compete with each other. From a security perspective, you should record all important operations so that any anomalous activity can later be identified. However, when private data is involved, this practice can create additional risk.

Although there are many ways in which private data can be handled unsafely, a common risk stems from misplaced trust. Programmers often trust the operating environment in which a program runs, and therefore believe that it is acceptable to store private information on the file system, in the registry, or in other locally-controlled resources. However, even if access to certain resources is restricted, it does not guarantee that the individuals who do have access can be trusted with certain data. For example, in 2004, an unscrupulous employee at AOL sold approximately 92 million private customer email addresses to a spammer marketing an offshore gambling web site [1].

In response to such high-profile exploits, the collection and management of private data is becoming increasingly regulated. Depending on its location, the type of business it conducts, and the nature of any private data it handles, an organization may be required to comply with one or more of the following federal and state regulations:

- Safe Harbor Privacy Framework [3]

- Gramm-Leach Bliley Act (GLBA) [4]

- Health Insurance Portability and Accountability Act (HIPAA) [5]

- California SB-1386 [6]

Despite these regulations, privacy violations continue to occur with alarming frequency.

The public key infrastructure (PKI) is based on trusted Ceritficate Authorities (CAs), however the increasing number of compromised Certificate Authorities means their root certificates can no longer be trusted and therefore no certificates that are signed by this CA can either. Attackers in possession of these compromised certificates will be able to intercept all the SSL/TLS traffic trusting these CAs.

Certificate Authorities signatures are necessary for general purpose network communication tools such as browsers that connect to arbitrary network endpoints and have no advance knowledge of which CAs sign the SSL/TLS certificates for those endpoints. Mobile applications that connect to a limited number of backend servers can benefit from knowing a shortlist of trusted CAs that these servers may use in signing their certificates and &quot;pin&quot; these certificates/public keys in the applications so that trust is reduced to the certificates the application expects.

<b>Example 1:</b> The following example establishes an SSL/TLS connection using the default pre-loaded system CAs.
<pre>
NSString* requestString = @"https://myserver.org";
NSURL* requestUrl = [NSURL URLWithString:requestString];
NSURLRequest* request = [NSURLRequest requestWithURL:requestUrl
                                         cachePolicy:NSURLRequestReloadIgnoringLocalCacheData
                                     timeoutInterval:10.0f];
NSURLConnection* connection = [[NSURLConnection alloc] initWithRequest:request delegate:self];
</pre>

Since there is no <code>NSURLConnectionDelegate</code> methods defined to handle certificate verification, it will use the system ones that will trust all the CAs present in the iOS default keystore.

Description.Recommendations:
There are several possible solutions to reduce the level of trust on pre-loaded system certificates including:

- Custom trust anchors: Use a custom keystore that only contains the certificates you want to trust.
- Certificate pinning: Trust the default certificates but verify and enforce that the one used by your backend server is present in the certificate chain. As an alternative, public keys can be pinned instead.

<b>Example 2:</b> The following example establishes an SSL/TLS connection using a custom keystore containing only the expected certificates.
<pre>
NSString* requestString = @"https://myserver.org";
NSURL* requestUrl = [NSURL URLWithString:requestString];
NSURLRequest* request = [NSURLRequest requestWithURL:requestUrl
                                         cachePolicy:NSURLRequestReloadIgnoringLocalCacheData
                                     timeoutInterval:10.0f];
NSURLConnection* connection = [[NSURLConnection alloc] initWithRequest:request delegate:self];

- (void)connection:(NSURLConnection *)connection didReceiveAuthenticationChallenge:(NSURLAuthenticationChallenge *)challenge {

    ...
    // Get a reference to the certificate presented by the server
    SecTrustRef serverTrust = [[challenge protectionSpace] serverTrust];
    if(!(nil != serverTrust)) gotoFail();
    CFIndex count = SecTrustGetCertificateCount(serverTrust);
	OSStatus status = SecTrustEvaluate(serverTrust, NULL);
	if(!(errSecSuccess == status)) gotoFail(); 
    SecCertificateRef serverCertificate = SecTrustGetCertificateAtIndex(serverTrust, 0);
    if(!(nil != serverCertificate)) gotoFail();
    // Perform the certificate verification
    ...
}
</pre>

<b>NOTE: </b> Do not use the code in <code>Example 2</code> in any application because it leaves out the verification step for brevity.

In this case, the <code>NSURLConnection</code> delegate is implementing a callback method to handle authentication and it is extracting the server's certificate and verifying it.

Description.Explanation:
Password management issues occur when a password is stored in plain text in an application's properties or configuration file. A programmer can attempt to remedy the password management problem by obscuring the password with an encoding function, such as base64 encoding, but this does not adequately protect the password.
<Paragraph>
In this case, the password is read into the program at <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/> and used to access a resource at <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>

<b>Example 1:</b> The following code reads a password from a <code>plist</code> file and uses it to unzip a password-protected file.
<pre>
...
NSDictionary *dict= [NSDictionary dictionaryWithContentsOfFile:[[NSBundle mainBundle] pathForResource:@"Config" ofType:@"plist"]];
NSString *encoded_password = [dict valueForKey:@"encoded_password"];
NSData *decodedData = [[NSData alloc] initWithBase64EncodedString:encoded_password options:0];
NSString *decodedString = [[NSString alloc] initWithData:decodedData encoding:NSUTF8StringEncoding];
[SSZipArchive unzipFileAtPath:zipPath toDestination:destPath overwrite:TRUE password:decodedString error:&amp;error];
...
</pre>

This code will run successfully, but anyone with access to the <code>Config.plist</code> file can read the value of <code>encoded_password</code> and easily determine that the value has been base64 encoded.

In the mobile environment, password management is especially important given that there is such a high chance of device loss.

Path Manipulation: Zip Entry Overwrite errors occur when a Zip file is opened and expanded without checking the file path of the Zip entry.

<b>Example 1:</b> The following example extracts files from a Zip file and insecurely writes them to disk.

<pre>
    ZZArchive* archive = [ZZArchive archiveWithURL:[NSURL fileURLWithPath: zipPath] error:&amp;error];
    for (ZZArchiveEntry* entry in archive.entries) {
        NSString *fullPath = [NSString stringWithFormat: @"%@/%@", destPath, [entry fileName]];
        [[entry newDataWithError:nil] writeToFile:newFullPath atomically:YES];
    }
</pre>

In <code>Example 1</code>, there is no validation of <code>entry.fileName</code> prior to performing read/write functions on the data within this entry. If the Zip file was originally placed in the directory "<code>Documents/hot_patches</code>" of an iOS application, a Zip entry was "<code>../js/page.js</code>", it would overwrite the <code>page.js</code> file. This in turn would enable an attacker to inject malicious code that might result in code execution.

Description.Recommendations:
The best way to prevent path manipulation via a Zip file is with a level of indirection. Create a list of legitimate path names to which a Zip entry can write, and write to the file that matches the Zip entry location. With this approach, the user input in the Zip file is never used directly to specify the file location.

This may be impractical in this example. Programmers often resort to implementing a deny list in these situations. A deny list is used to selectively reject or escape potentially dangerous characters before using the input. However, any such list of unsafe characters is likely to be incomplete and will almost certainly become out-of-date. A better approach is to create a list of characters that are permitted to appear in the resource name and accept input composed exclusively of characters in the approved set.

In this case, APIs such as <code>NSString.stringByStandardizingPathg</code> can be used to retrieve the canonicalized form of the file path, which can be used for checking the directory in which the file will be written.

<b>Example 2:</b> The following example extracts files from a Zip file and securely writes them to disk.

<pre>
    ZZArchive* archive = [ZZArchive archiveWithURL:[NSURL fileURLWithPath: zipPath] error:&amp;error];
    for (ZZArchiveEntry* entry in archive.entries) {
        NSString *fullPath = [NSString stringWithFormat: @"%@/%@", destPath, [entry fileName]];
        NSString *normalizedPath = [fullPath stringByStandardizingPath];
        if ([normalizedFullPath hasPrefix:destPath]) {
            [[entry newDataWithError:nil] writeToFile:newFullPath atomically:YES];
        }
    }
</pre>

Description.Explanation:
Application files can be accessed by other applications on rooted devices or in unencrypted backups. Because a user could decide to jailbreak their device or perform unencrypted backups, it is a best practice to encrypt databases that contain sensitive data.

<b>Example 1:</b> The following code establishes a connection to an unencrypted <code>Realm</code> database:

<pre>
    RLMRealmConfiguration *config = [RLMRealmConfiguration defaultConfiguration];
    RLMRealm *realm = [RLMRealm realmWithConfiguration:config error:nil];
</pre>

Description.Recommendations:
On iOS 8 and later, files inside apps are automatically encrypted using the <code>NSFileProtection</code> API when the device is locked. However, the default iOS Data Protection API can leave data unencrypted in certain situations such as when no <code>PIN</code> is set and the device is unlocked. Therefore, to protect user data, it is always preferable to encrypt the database.

<b>Example 2:</b> The following code uses the <code>Realm</code> database native encryption, which uses <code>AES-256+SHA2</code> to transparently protect the database at rest:

<pre>
    RLMRealmConfiguration *config = [RLMRealmConfiguration defaultConfiguration];
    config.encryptionKey = [self getKeyFromKeyChain];
    RLMRealm *realm = [RLMRealm realmWithConfiguration:config error:nil];
</pre>

The safest option for <code>Realm</code> files created specifically on a single device where the files are guaranteed to remain on the device, is to save the encryption key to the system security keychain.

Description.Explanation:
Application files can be accessed by other applications on rooted devices or in unencrypted backups. Because a user could decide to jailbreak their device or perform unencrypted backups, it is a best practice to encrypt databases that contain sensitive data.

<b>Example 1:</b> The following code establishes a connection to an unencrypted <code>Realm</code> database:

<pre>
    RLMRealmConfiguration *config = [RLMRealmConfiguration defaultConfiguration];
    RLMRealm *realm = [RLMRealm realmWithConfiguration:config error:nil];
</pre>

Description.Recommendations:
On iOS 8 and later, files inside apps are automatically encrypted using the <code>NSFileProtection</code> API when the device is locked. However, the default iOS Data Protection API can leave data unencrypted in certain situations such as when no <code>PIN</code> is set and the device is unlocked. Therefore, to protect user data, it is always preferable to encrypt the database.

<b>Example 2:</b> The following code uses the <code>Realm</code> database native encryption, which uses <code>AES-256+SHA2</code> to transparently protect the database at rest:

<pre>
    RLMRealmConfiguration *config = [RLMRealmConfiguration defaultConfiguration];
    config.encryptionKey = [self getKeyFromKeyChain];
    RLMRealm *realm = [RLMRealm realmWithConfiguration:config error:nil];
</pre>

The safest option for <code>Realm</code> files created specifically on a single device where the files are guaranteed to remain on the device, is to save the encryption key to the system security keychain.
